// GENERATED FILE. Source of truth: docs/data/biblia-emanus/*.json
import type { PublishedEmanusOtTextBook } from "../publishedEmanusOtText.js"

export const EMANUS_TEXT_BOOK: PublishedEmanusOtTextBook = {
  order: 3,
  code: "LEV",
  name: "Leviticul",
  chapters: {
    1: ["DOMNUL l-a chemat pe Moise și i-a vorbit din Cortul Întâlnirii:", "„Vorbește-le fiilor lui Israel și spune-le: «Când cineva dintre voi aduce un dar DOMNULUI, să-și aducă darul dintre animale, fie din cireadă, fie din turmă.", "Dacă darul lui este o ardere-de-tot din cireadă, să aducă un mascul fără cusur. Să-l aducă la intrarea Cortului Întâlnirii, ca să fie primit înaintea DOMNULUI.", "Să-și pună mâna pe capul animalului adus ca ardere-de-tot, iar acesta va fi primit pentru el ca să se facă ispășire pentru el.", "El să înjunghie taurul înaintea DOMNULUI, iar fiii lui Aaron, preoții, să prezinte sângele și să-l stropească de jur împrejur pe altarul de la intrarea Cortului Întâlnirii.", "Să jupoaie arderea-de-tot și să o taie în bucăți.", "Fiii preotului Aaron să pună foc pe altar și să așeze lemnele pe foc.", "Preoții, fiii lui Aaron, să așeze bucățile, capul și grăsimea pe lemnele puse pe focul de pe altar.", "El să spele cu apă măruntaiele și picioarele, iar preotul să ardă totul pe altar ca ardere-de-tot, o jertfă mistuită de foc, o mireasmă plăcută DOMNULUI.", "Dacă darul lui este din turmă, din miei sau din capre, pentru o ardere-de-tot, să aducă un mascul fără cusur.", "Să-l junghie pe partea de nord a altarului, înaintea DOMNULUI, iar fiii lui Aaron, preoții, să stropească cu sângele lui pe altar de jur împrejur.", "Să-l taie în bucăți, împreună cu capul și grăsimea lui, iar preotul să le așeze pe lemnele puse pe focul de pe altar.", "Măruntaiele și picioarele să le spele cu apă, iar preotul să le aducă pe toate și să le ardă pe altar. Aceasta este o ardere-de-tot, o jertfă mistuită de foc, de o mireasmă plăcută DOMNULUI.", "Dacă darul adus ca ardere-de-tot DOMNULUI este din păsări, să-și aducă darul din turturele sau din pui de porumbel.", "Preotul să aducă pasărea la altar, să-i frângă capul la ceafă și să-l ardă pe altar, iar sângele ei să fie scurs pe peretele altarului.", "Să-i scoată gușa împreună cu conținutul ei și să o arunce lângă altar, spre răsărit, în locul cenușii.", "Să o despice între aripi, fără să o despartă în două, iar preotul să o ardă pe altar, pe lemnele puse pe foc. Este o ardere-de-tot, o jertfă mistuită de foc, o mireasmă plăcută DOMNULUI.»”"],
    2: ["„Când cineva aduce DOMNULUI un dar de cereale, darul lui să fie din făină fină. Să toarne ulei peste el și să pună tămâie peste el.", "Să-l aducă fiilor lui Aaron, preoții. Preotul să ia un pumn din făina fină și din ulei, împreună cu toată tămâia, și să ardă pe altar partea de aducere-aminte, ca jertfă mistuită de foc, o mireasmă plăcută DOMNULUI.", "Ce rămâne din darul de cereale să fie al lui Aaron și al fiilor lui; este o parte preasfântă din jertfele mistuite de foc ale DOMNULUI.", "Dacă aduci un dar de cereale copt în cuptor, să fie din turte de făină fină fără aluat, frământate cu ulei, sau din foițe fără aluat, unse cu ulei.", "Dacă darul tău este un dar de cereale pregătit pe plită, să fie din făină fină fără aluat, frământată cu ulei.", "Să-l rupi în bucăți și să torni ulei peste el; este un dar de cereale.", "Dacă darul tău este un dar de cereale pregătit într-o tigaie, să fie făcut din făină fină cu ulei.", "Să aduci DOMNULUI darul de cereale făcut din aceste lucruri, să-l înfățișezi preotului, iar el să-l aducă la altar.", "Preotul să ia din darul de cereale partea de aducere-aminte și să o ardă pe altar ca jertfă mistuită de foc, o mireasmă plăcută DOMNULUI.", "Ce rămâne din darul de cereale să fie al lui Aaron și al fiilor lui; este o parte preasfântă din jertfele mistuite de foc ale DOMNULUI.", "Niciun dar de cereale pe care îl aduceți DOMNULUI să nu fie pregătit cu aluat dospit, căci nu trebuie să ardeți pe altar nici aluat dospit, nici miere ca jertfă mistuită de foc pentru DOMNUL.", "Le puteți aduce DOMNULUI ca dar din primele roade, dar să nu fie înălțate pe altar ca mireasmă plăcută.", "Să sărezi cu sare fiecare dar de cereale. Să nu lași să lipsească din darul tău de cereale sarea legământului Dumnezeului tău. Împreună cu toate darurile tale să aduci sare.", "Dacă aduci DOMNULUI un dar de cereale din primele roade, să aduci spice proaspete prăjite la foc, boabe zdrobite din grâne noi.", "Să torni ulei peste el și să pui tămâie peste el; este un dar de cereale.", "Preotul să ardă ca aducere-aminte o parte din boabele zdrobite și din ulei, împreună cu toată tămâia; este o jertfă mistuită de foc pentru DOMNUL.”"],
    3: ["„Dacă darul cuiva este o jertfă de pace și aduce din cireadă, fie mascul, fie femelă, să aducă înaintea DOMNULUI un animal fără cusur.", "Să-și pună mâna pe capul jertfei sale și să o junghie la intrarea Cortului Întâlnirii, iar fiii lui Aaron, preoții, să stropească sângele pe altar de jur împrejur.", "Din jertfa de pace să aducă drept jertfă mistuită de foc pentru DOMNUL grăsimea care acoperă măruntaiele și toată grăsimea de pe măruntaie,", "cei doi rinichi cu grăsimea de pe ei, de lângă coapse, și lobul ficatului, pe care să-l îndepărteze împreună cu rinichii.", "Fiii lui Aaron să le ardă pe altar, peste arderea-de-tot care este pe lemnele de pe foc. Aceasta este o jertfă mistuită de foc, o mireasmă plăcută DOMNULUI.", "Dacă darul lui pentru o jertfă de pace adusă DOMNULUI este din turmă, fie mascul, fie femelă, să-l aducă fără cusur.", "Dacă aduce un miel ca dar al său, să-l aducă înaintea DOMNULUI.", "Să-și pună mâna pe capul jertfei sale și să o junghie înaintea Cortului Întâlnirii, iar fiii lui Aaron să stropească sângele ei pe altar de jur împrejur.", "Din jertfa de pace să aducă drept jertfă mistuită de foc pentru DOMNUL grăsimea ei: întreaga coadă grasă, tăiată aproape de șira spinării, grăsimea care acoperă măruntaiele și toată grăsimea de pe măruntaie,", "cei doi rinichi cu grăsimea de pe ei, de lângă coapse, și lobul ficatului, pe care să-l îndepărteze împreună cu rinichii.", "Preotul să le ardă pe altar; aceasta este hrana jertfei mistuite de foc pentru DOMNUL.", "Dacă darul lui este o capră, să o aducă înaintea DOMNULUI.", "Să-și pună mâna pe capul ei și să o junghie înaintea Cortului Întâlnirii, iar fiii lui Aaron să stropească sângele ei pe altar de jur împrejur.", "Din ea să-și aducă darul ca jertfă mistuită de foc pentru DOMNUL: grăsimea care acoperă măruntaiele și toată grăsimea de pe măruntaie,", "cei doi rinichi cu grăsimea de pe ei, de lângă coapse, și lobul ficatului, pe care să-l îndepărteze împreună cu rinichii.", "Preotul să le ardă pe altar. Aceasta este hrana jertfei mistuite de foc, o mireasmă plăcută. Toată grăsimea este a DOMNULUI.", "Aceasta să fie o rânduială veșnică pentru generațiile voastre, în toate locuințele voastre: să nu mâncați grăsimea rezervată jertfei și nici sânge.”"],
    4: ["DOMNUL i-a vorbit lui Moise și i-a spus:", "„Vorbește-le fiilor lui Israel: «Dacă cineva păcătuiește fără intenție, încălcând una dintre poruncile DOMNULUI și făcând ceva ce nu trebuie făcut,", "dacă preotul uns păcătuiește și aduce vină asupra poporului, să aducă DOMNULUI pentru păcatul său un taur tânăr fără cusur, ca jertfă pentru păcat.", "Să aducă taurul la intrarea Cortului Întâlnirii, înaintea DOMNULUI, să-și pună mâna pe capul taurului și să junghie taurul înaintea DOMNULUI.", "Preotul cel uns să ia din sângele taurului și să îl ducă în Cortul Întâlnirii.", "Preotul să-și înmoaie degetul în sânge și să stropească de șapte ori din sânge înaintea DOMNULUI, în fața perdelei sanctuarului.", "Preotul să pună din sânge pe coarnele altarului tămâierii miresmelor, care este în Cortul Întâlnirii înaintea DOMNULUI, iar tot celălalt sânge al taurului să-l verse la baza altarului arderii-de-tot, care este la intrarea Cortului Întâlnirii.", "Toată grăsimea taurului jertfei pentru păcat să o ridice de pe el: grăsimea care acoperă măruntaiele și toată grăsimea de pe măruntaie,", "cei doi rinichi cu grăsimea de pe ei, de lângă coapse, și rețeaua de pe ficat, pe care o va disloca împreună cu rinichii,", "să le îndepărteze așa cum sunt îndepărtate de la taurul jertfei de pace. Preotul să le ardă pe altarul arderii-de-tot.", "Dar pielea taurului și toată carnea lui, cu capul, picioarele, măruntaiele și bălegarul lui,", "adică tot taurul, să îl scoată afară din tabără, într-un loc curat, unde se aruncă cenușa, și să îl ardă pe lemne în foc; unde se aruncă cenușa, acolo să fie ars.", "Dacă întreaga comunitate a lui Israel păcătuiește fără intenție, iar lucrul este ascuns de ochii adunării, și încalcă una dintre poruncile DOMNULUI, devenind vinovată,", "când se va cunoaște păcatul pe care l-au săvârșit, adunarea să aducă un taur din cireadă ca jertfă pentru păcat și să îl aducă înaintea Cortului Întâlnirii.", "Bătrânii adunării să-și pună mâinile pe capul taurului înaintea DOMNULUI și taurul să fie junghiat înaintea DOMNULUI.", "Preotul cel uns să aducă din sângele taurului în Cortul Întâlnirii.", "Preotul să-și moaie degetul în sânge și să stropească de șapte ori înaintea DOMNULUI, înaintea perdelei.", "Să pună din sânge pe coarnele altarului care este înaintea DOMNULUI, în Cortul Întâlnirii, iar tot celălalt sânge să-l verse la baza altarului arderii-de-tot, care este la intrarea Cortului Întâlnirii.", "Toată grăsimea taurului să o scoată de pe el și să o ardă pe altar.", "Să facă cu taurul acesta așa cum a făcut cu taurul jertfei pentru păcat. Astfel preotul va face ispășire pentru ei și vor fi iertați.", "Apoi să scoată taurul afară din tabără și să îl ardă cum a ars primul taur. Aceasta este jertfa pentru păcat a adunării.", "Dacă un conducător păcătuiește și, fără intenție, încalcă una dintre poruncile DOMNULUI, Dumnezeul său, devenind vinovat,", "sau dacă i se va aduce la cunoștință păcatul pe care l-a comis, să aducă drept prinos al său un țap fără cusur.", "Să-și pună mâna pe capul țapului și să îl junghie în locul unde se junghie jertfele de ardere de tot înaintea DOMNULUI; este o jertfă pentru păcat.", "Preotul să ia cu degetul din sângele jertfei pentru păcat și să pună pe coarnele altarului arderii-de-tot, iar celălalt sânge să-l verse la baza altarului arderii-de-tot.", "Toată grăsimea lui să o ardă pe altar ca grăsimea jertfei de pace. Preotul să facă ispășire pentru el de păcatul lui și îi va fi iertat.", "Dacă cineva din poporul țării păcătuiește fără intenție, încălcând una dintre poruncile DOMNULUI și devenind vinovat,", "sau dacă i se va aduce la cunoștință păcatul pe care l-a săvârșit, să aducă drept dar al său o capră fără cusur, o femelă, pentru păcatul pe care l-a comis.", "Să-și pună mâna pe capul jertfei pentru păcat și să junghie jertfa pentru păcat în locul arderii de tot.", "Preotul să ia cu degetul din sângele ei și să pună pe coarnele altarului arderii-de-tot, iar tot celălalt sânge să-l verse la baza altarului.", "Să îndepărteze toată grăsimea, așa cum este îndepărtată grăsimea de la jertfa de pace, iar preotul să o ardă pe altar ca mireasmă plăcută DOMNULUI. Astfel preotul va face ispășire pentru el și va fi iertat.", "Dacă va aduce un miel ca prinos al său pentru păcat, să aducă o femelă fără cusur.", "Să-și pună mâna pe capul jertfei pentru păcat și să o junghie ca jertfă pentru păcat în locul unde se junghie jertfele de ardere de tot.", "Preotul să ia cu degetul din sângele jertfei pentru păcat și să pună pe coarnele altarului arderii-de-tot, iar tot celălalt sânge să-l verse la baza altarului.", "Toată grăsimea ei să o scoată, cum se scoate grăsimea mielului din jertfa de pace, iar preotul să le ardă pe altar, peste jertfele mistuite de foc pentru DOMNUL. Astfel preotul va face ispășire pentru el de păcatul pe care l-a comis și îi va fi iertat.»”"],
    5: ["„Dacă cineva păcătuiește pentru că aude o chemare publică la mărturie și, deși este martor — a văzut sau cunoaște lucrul — nu îl declară, își va purta vina.", "Dacă cineva atinge un lucru necurat — cadavrul unui animal sălbatic necurat, cadavrul unui animal domestic necurat sau cadavrul unei vietăți târâtoare necurate — chiar dacă nu și-a dat seama, devine necurat și vinovat.", "Dacă atinge necurăția unui om, oricare ar fi necurăția care îl face necurat, și nu și-a dat seama, când află devine vinovat.", "Dacă cineva jură pripit cu buzele să facă rău sau bine — orice ar rosti omul pripit prin jurământ — și nu și-a dat seama, când află devine vinovat în unul dintre aceste cazuri.", "Când devine vinovat în unul dintre aceste cazuri, să mărturisească păcatul pe care l-a comis.", "Să aducă DOMNULUI, pentru vina păcatului comis, o femelă din turmă, o oaie sau o capră, ca jertfă pentru păcat. Preotul să facă ispășire pentru el cu privire la păcatul lui.", "Dacă nu-și permite un animal din turmă, să aducă DOMNULUI pentru vina sa două turturele sau doi pui de porumbel: unul ca jertfă pentru păcat și celălalt ca ardere-de-tot.", "Să-i aducă preotului, iar el va aduce mai întâi pe cel rânduit ca jertfă pentru păcat și îi va frânge capul de la gât, fără să-l despartă.", "Să stropească din sângele jertfei pentru păcat pe peretele altarului, iar restul sângelui să fie stors la baza altarului; este o jertfă pentru păcat.", "Pe celălalt să-l pregătească ca ardere-de-tot, după rânduială. Astfel preotul va face ispășire pentru el de păcatul pe care l-a comis și îi va fi iertat.", "Dacă nu-și permite nici două turturele sau doi pui de porumbel, să aducă pentru păcatul său a zecea parte dintr-o efă de făină fină, ca jertfă pentru păcat. Să nu pună ulei sau tămâie peste ea, fiindcă este o jertfă pentru păcat.", "Să o aducă preotului, iar preotul să ia din ea un pumn plin ca aducere aminte și să o ardă pe altar peste jertfele mistuite de foc pentru DOMNUL; este o jertfă pentru păcat.", "Preotul va face ispășire pentru el de păcatul pe care l-a comis într-unul din aceste lucruri și îi va fi iertat. Restul va fi al preotului, ca la darul de cereale.”", "DOMNUL i-a vorbit lui Moise, spunând:", "„Dacă cineva comite o încălcare și păcătuiește fără intenție cu privire la lucrurile sfinte ale DOMNULUI, să aducă DOMNULUI ca jertfă pentru vină un berbec fără cusur din turmă, evaluat în șecheli de argint după șechelul sanctuarului.", "Să restituie ceea ce a folosit greșit din lucrul sfânt, să adauge a cincea parte și să o dea preotului. Preotul să facă ispășire pentru el cu berbecul jertfei pentru vină, iar el va fi iertat.", "Dacă cineva păcătuiește încălcând una dintre poruncile DOMNULUI, chiar dacă nu a știut, este vinovat și își va purta nelegiuirea.", "Să aducă preotului un berbec fără cusur din turmă, la prețuirea ta, ca jertfă pentru vină. Preotul va face ispășire pentru el de greșeala săvârșită din neatenție, fără să știe, și îi va fi iertat.", "Este o jertfă pentru vină; el este cu adevărat vinovat înaintea DOMNULUI.”"],
    6: ["DOMNUL i-a vorbit lui Moise și i-a spus:", "„Dacă cineva păcătuiește și se poartă cu necredincioșie față de DOMNUL, mințindu-și semenul cu privire la un lucru încredințat, la un bun dat în păstrare, la un lucru furat sau dacă își asuprește semenul,", "ori găsește un lucru pierdut și minte cu privire la el, jurând fals în oricare dintre lucrurile prin care omul păcătuiește,", "când păcătuiește astfel și devine vinovat, să restituie lucrul furat, bunul luat prin asuprire, lucrul încredințat lui sau lucrul pierdut pe care l-a găsit,", "ori orice lucru cu privire la care a jurat fals. Să-l restituie integral, să adauge a cincea parte și să-l dea proprietarului în ziua în care își recunoaște vina.", "Să aducă preotului pentru DOMNUL, ca jertfă pentru vină, un berbec fără cusur din turmă, evaluat potrivit valorii stabilite.", "Preotul va face ispășire pentru el înaintea DOMNULUI și îi va fi iertat orice lucru prin care s-a făcut vinovat.”", "DOMNUL i-a vorbit lui Moise, spunând:", "„Poruncește-le lui Aaron și fiilor lui: «Aceasta este legea arderii-de-tot: arderea-de-tot să rămână pe vatra altarului toată noaptea până dimineața, iar focul altarului să fie ținut aprins pe el.", "Preotul să se îmbrace cu veșmântul său de in și să-și pună pantalonii de in pe trup. Să ridice cenușa rămasă după ce focul a mistuit arderea-de-tot pe altar și să o pună lângă altar.", "Apoi să-și schimbe hainele și să se îmbrace cu alte haine, ca să scoată cenușa afară din tabără, într-un loc curat.", "Focul de pe altar să fie ținut aprins pe el; să nu se stingă. Preotul să ardă lemne pe el în fiecare dimineață, să așeze arderea-de-tot pe el și să ardă pe el grăsimile jertfelor de pace.", "Focul să ardă permanent pe altar; să nu se stingă.", "Aceasta este legea darului de mâncare: fiii lui Aaron să-l prezinte înaintea DOMNULUI, în fața altarului.", "Preotul să ia din el un pumn din făina fină și din ulei, împreună cu toată tămâia de pe darul de mâncare, și să ardă pe altar partea de aducere-aminte, ca mireasmă plăcută DOMNULUI.", "Ce va rămâne din ea să mănânce Aaron și fiii lui. Să fie mâncată fără aluat într-un loc sfânt; în curtea Cortului Întâlnirii să o mănânce.", "Să nu fie coaptă cu aluat. Le-am dat-o ca parte a lor din jertfele Mele mistuite de foc; este un lucru preasfânt, ca și jertfa pentru păcat și jertfa pentru vină.", "Orice bărbat dintre urmașii lui Aaron poate mânca din el. Aceasta este partea lor pentru totdeauna, din generație în generație, din jertfele mistuite de foc ale DOMNULUI. Orice lucru care le atinge va deveni sfânt.»”", "DOMNUL i-a vorbit lui Moise, spunând:", "„Acesta este darul pe care Aaron și fiii lui îl vor aduce DOMNULUI în ziua în care va fi uns: a zecea parte dintr-o efă de făină fină, ca dar de mâncare permanent, jumătate dimineața și jumătate seara.", "Să fie pregătită pe plită cu ulei; o vei aduce frământată și vei aduce bucățile coapte ale darului de mâncare ca miros plăcut DOMNULUI.", "Preotul uns dintre fiii lui, care îi va urma, să o pregătească. Este o rânduială veșnică pentru DOMNUL: să fie arsă în întregime.", "Orice dar de mâncare al unui preot să fie ars în întregime; să nu fie mâncat.”", "DOMNUL i-a vorbit lui Moise, spunând:", "„Vorbește-le lui Aaron și fiilor lui: «Aceasta este legea jertfei pentru păcat: jertfa pentru păcat să fie înjunghiată înaintea DOMNULUI în locul unde este înjunghiată arderea-de-tot. Este preasfântă.", "Preotul care o aduce ca jertfă pentru păcat să o mănânce. Să fie mâncată într-un loc sfânt, în curtea Cortului Întâlnirii.", "Orice lucru care îi atinge carnea va deveni sfânt. Dacă sângele ei stropește o haină, partea stropită să fie spălată într-un loc sfânt.", "Vasul de lut în care a fost fiartă să fie spart; iar dacă a fost fiartă într-un vas de aramă, acesta să fie frecat și spălat cu apă.", "Orice parte bărbătească dintre preoți poate mânca din ea; este un lucru preasfânt.", "Dar nicio jertfă pentru păcat din al cărei sânge este adus în Cortul Întâlnirii ca să se facă ispășire în Locul Sfânt să nu fie mâncată; să fie arsă în foc.»”"],
    7: ["„Aceasta este legea jertfei pentru vină. Ea este preasfântă.", "Jertfa pentru vină să fie înjunghiată în locul unde este înjunghiată arderea-de-tot, iar sângele ei să fie stropit de jur împrejur pe altar.", "Să fie adusă toată grăsimea ei: coada grasă și grăsimea care acoperă măruntaiele,", "cei doi rinichi cu grăsimea de pe ei, de lângă coapse, și lobul ficatului, care va fi îndepărtat împreună cu rinichii.", "Preotul să le ardă pe altar ca jertfă mistuită de foc pentru DOMNUL; este o jertfă pentru vină.", "Orice parte bărbătească dintre preoți poate mânca din ea; să fie mâncată într-un loc sfânt, căci este un lucru preasfânt.", "Jertfa pentru păcat și jertfa pentru vină au aceeași lege. Ea va fi a preotului care face ispășire prin ea.", "Preotul care aduce arderea-de-tot a cuiva va avea pentru sine pielea arderii-de-tot pe care a adus-o.", "Orice dar de mâncare coaptă în cuptor sau pregătită în tigaie sau pe plită va fi a preotului care o aduce.", "Dar orice dar de mâncare frământată cu ulei sau uscată va fi a tuturor fiilor lui Aaron, a unuia ca și a altuia.", "Aceasta este legea jertfei de pace pe care cineva o aduce DOMNULUI:", "Dacă o aduce ca mulțumire, să aducă împreună cu jertfa de mulțumire turte nedospite frământate cu ulei, lipii nedospite unse cu ulei și turte din făină fină bine amestecate cu ulei.", "Împreună cu jertfa de pace adusă ca mulțumire să-și aducă darul și cu turte de pâine dospită.", "Din fiecare fel să aducă o bucată drept contribuție pentru DOMNUL. Ea va fi a preotului care stropește sângele jertfei de pace.", "Carnea jertfei sale de pace adusă ca mulțumire să fie mâncată în ziua aducerii ei; să nu lase nimic din ea până dimineața.", "Dacă jertfa pe care o aduce ca prinos este un jurământ sau un dar de bunăvoie, să fie mâncată în ziua când își aduce jertfa, iar ce va rămâne din ea să se mănânce a doua zi.", "Dar ce va mai rămâne din carnea jertfei până în ziua a treia să fie ars în foc.", "Dacă se mănâncă din carnea jertfei de pace în ziua a treia, jertfa nu va fi primită și nu-i va fi socotită celui care a adus-o; va fi un lucru respingător, iar cel care mănâncă din ea își va purta vina.", "Carnea care se va atinge de ceva necurat să nu se mănânce, ci să fie arsă în foc. Cât despre altă carne, oricine este curat poate mânca din ea.", "Persoana care mănâncă din carnea jertfei de pace care Îi aparține DOMNULUI, în timp ce necurăția este asupra ei, va fi îndepărtată din poporul ei.", "Dacă cineva se va atinge de ceva necurat, de necurăția unui om, de un animal necurat sau de orice urâciune necurată și va mânca din carnea jertfei de pace a DOMNULUI, omul acela să fie nimicit din poporul său.", "DOMNUL i-a vorbit lui Moise, spunând:", "«Vorbește fiilor lui Israel și spune-le: Să nu mâncați niciun fel de grăsime de taur, de miel sau de capră.", "Grăsimea unui animal mort de la sine sau sfâșiat de fiare poate fi folosită pentru alte scopuri, dar să nu o mâncați.", "Cine mănâncă din grăsimea unui animal din care se aduce DOMNULUI o jertfă mistuită de foc va fi îndepărtat din poporul său.", "Să nu mâncați niciun fel de sânge, nici de pasăre, nici de animal, în toate locuințele voastre.", "Oricine mănâncă sânge va fi îndepărtat din poporul său.»", "DOMNUL i-a vorbit lui Moise, spunând:", "«Vorbește fiilor lui Israel și spune-le: Cine își aduce jertfa sa de pace DOMNULUI să aducă prinosul său DOMNULUI din jertfa lui de pace.", "Să aducă prin propriile mâini jertfele mistuite de foc ale DOMNULUI. Să aducă grăsimea împreună cu pieptul, pentru ca pieptul să fie legănat ca dar legănat înaintea DOMNULUI.", "Preotul să ardă grăsimea pe altar, iar pieptul să fie al lui Aaron și al fiilor lui.", "Pulpa dreaptă din jertfele voastre de pace să o dați preotului drept contribuție.", "Aceluia dintre fiii lui Aaron care va aduce sângele jertfelor de pace și grăsimea, aceluia îi va reveni pulpa dreaptă ca parte a lui.", "Căci am luat de la fiii lui Israel, din jertfele lor de pace, pieptul darului legănat și pulpa contribuției și le-am dat preotului Aaron și fiilor lui ca parte permanentă din partea fiilor lui Israel.»", "Aceasta este partea lui Aaron și partea fiilor lui din jertfele mistuite de foc ale DOMNULUI, din ziua când au fost aduși ca să-I slujească DOMNULUI în preoție,", "pe care DOMNUL a poruncit fiilor lui Israel să le-o dea în ziua când i-a uns; este o rânduială veșnică pentru generațiile lor.", "Aceasta este legea arderii-de-tot, a darului de mâncare, a jertfei pentru păcat, a jertfei pentru vină, a învestirii și a jertfei de pace,", "pe care DOMNUL i-a poruncit-o lui Moise pe Muntele Sinai, în ziua când le-a poruncit fiilor lui Israel să-și aducă darurile DOMNULUI în Pustiul Sinai.”"],
    8: ["DOMNUL i-a vorbit lui Moise și i-a spus:", "„Ia-i pe Aaron și pe fiii lui împreună cu el, veșmintele, untdelemnul ungerii, taurul jertfei pentru păcat, cei doi berbeci și coșul cu azime.", "și adună toată comunitatea la intrarea Cortului Întâlnirii.”", "Moise a făcut așa cum îi poruncise DOMNUL și comunitatea s-a adunat la intrarea Cortului Întâlnirii.", "Moise a spus adunării: „Acesta este lucrul pe care DOMNUL a poruncit să fie făcut.”", "Moise i-a apropiat pe Aaron și pe fiii lui și i-a spălat cu apă.", "I-a pus lui Aaron tunica, l-a încins cu brâul, l-a îmbrăcat cu mantia, i-a pus efodul și l-a încins cu brâul artistic al efodului, strângându-l pe el.", "I-a pus pieptarul și a așezat în pieptar Urim și Tumim.", "I-a pus mitra pe cap, iar pe mitră, în față, a pus tăblița de aur, coroana sfântă, așa cum îi poruncise DOMNUL lui Moise.", "Moise a luat uleiul ungerii și a uns Cortul și tot ce era în el, sfințindu-le.", "A stropit din el de șapte ori pe altar și a uns altarul și toate uneltele lui, precum și ligheanul cu piciorul lui, ca să le sfințească.", "A turnat din untdelemnul ungerii pe capul lui Aaron și l-a uns ca să-l sfințească.", "Moise i-a apropiat și pe fiii lui Aaron, i-a îmbrăcat cu tunici, i-a încins cu brâie și le-a legat scufiile, așa cum îi poruncise DOMNUL lui Moise.", "A adus taurul jertfei pentru păcat, iar Aaron și fiii lui și-au pus mâinile pe capul taurului jertfei pentru păcat.", "Moise a înjunghiat taurul, a luat sângele, a pus cu degetul pe coarnele altarului de jur împrejur și a curățit altarul. A turnat sângele la baza altarului și l-a sfințit, făcând ispășire pentru el.", "Moise a luat toată grăsimea de pe măruntaie, rețeaua ficatului și cei doi rinichi cu grăsimea lor și le-a ars pe altar.", "Iar taurul, pielea lui, carnea lui și bălegarul lui le-a ars în foc afară din tabără, așa cum îi poruncise DOMNUL lui Moise.", "A adus berbecul arderii-de-tot, iar Aaron și fiii lui și-au pus mâinile pe capul berbecului.", "Moise l-a junghiat și a stropit sângele pe altar de jur împrejur.", "A tăiat berbecul în bucăți și a ars capul, bucățile și grăsimea.", "A spălat măruntaiele și picioarele cu apă, iar Moise a ars tot berbecul pe altar ca ardere-de-tot de o mireasmă plăcută, o jertfă mistuită de foc pentru DOMNUL, așa cum îi poruncise DOMNUL lui Moise.", "A adus și al doilea berbec, berbecul consacrării, iar Aaron și fiii lui și-au pus mâinile pe capul berbecului.", "Moise a înjunghiat berbecul și a luat din sângele lui, punând pe lobul urechii drepte a lui Aaron, pe degetul mare al mâinii lui drepte și pe degetul mare al piciorului lui drept.", "Moise i-a apropiat și pe fiii lui Aaron și a pus din sânge pe lobul urechii lor drepte, pe degetul mare al mâinii lor drepte și pe degetul mare al piciorului lor drept, iar restul sângelui l-a stropit pe altar de jur împrejur.", "A luat grăsimea, coada întreagă, toată grăsimea de pe măruntaie, rețeaua ficatului, cei doi rinichi cu grăsimea lor și pulpa dreaptă.", "Din coșul cu pâini fără aluat care era înaintea DOMNULUI a luat o turtă fără aluat, o turtă de pâine cu ulei și o foiță și le-a pus pe grăsimi și pe pulpa dreaptă.", "A pus toate acestea în mâinile lui Aaron și în mâinile fiilor lui și le-a legănat ca dar legănat înaintea DOMNULUI.", "Moise le-a luat din palmele lor și le-a ars pe altar, peste arderea-de-tot. Ele au fost o jertfă de consacrare de o mireasmă plăcută, o jertfă mistuită de foc pentru DOMNUL.", "Moise a luat pieptul și l-a legănat ca dar legănat înaintea DOMNULUI; din berbecul consacrării, aceasta a fost partea lui Moise, așa cum îi poruncise DOMNUL lui Moise.", "Moise a luat din untdelemnul ungerii și din sângele de pe altar și a stropit pe Aaron și veșmintele lui, pe fiii lui și veșmintele fiilor lui. Astfel i-a sfințit pe Aaron și veșmintele lui, pe fiii lui și veșmintele fiilor lui.", "Moise i-a zis lui Aaron și fiilor lui: „Fierbeți carnea la intrarea Cortului Întâlnirii și mâncați-o acolo, împreună cu pâinea din coșul consacrării, așa cum am poruncit, spunând: Aaron și fiii lui să o mănânce.", "Iar ce va rămâne din carne și din pâine să ardeți în foc.", "Să nu ieșiți de la intrarea Cortului Întâlnirii timp de șapte zile, până când se vor împlini zilele învestirii voastre, căci învestirea voastră va dura șapte zile.", "Ceea ce s-a făcut astăzi a poruncit DOMNUL să fie făcut pentru a se face ispășire pentru voi.", "Să rămâneți la intrarea Cortului Întâlnirii zi și noapte timp de șapte zile și să păziți porunca DOMNULUI, ca să nu muriți, căci așa mi s-a poruncit.”", "Aaron și fiii lui au făcut toate lucrurile pe care le poruncise DOMNUL prin Moise."],
    9: ["În ziua a opta, Moise i-a chemat pe Aaron, pe fiii lui și pe bătrânii lui Israel.", "I-a spus lui Aaron: „Ia un vițel din cireadă ca jertfă pentru păcat și un berbec ca ardere-de-tot, amândoi fără cusur, și adu-i înaintea DOMNULUI.", "Iar fiilor lui Israel spune-le astfel: Luați un țap ca jertfă pentru păcat, un vițel și un miel, ambii de un an și fără cusur, ca ardere-de-tot,", "și un taur și un berbec ca jertfe de pace, ca să le jertfiți înaintea DOMNULUI, împreună cu un dar de mâncare amestecat cu ulei, căci astăzi vi Se va arăta DOMNUL.”", "Au adus în fața Cortului Întâlnirii ce poruncise Moise și toată comunitatea s-a apropiat și a stat înaintea DOMNULUI.", "Moise a spus: „Acesta este lucrul pe care DOMNUL a poruncit să-l faceți, iar gloria DOMNULUI vi se va arăta.”", "Moise i-a spus lui Aaron: „Apropie-te de altar, adu jertfa ta pentru păcat și arderea ta de tot și fă ispășire pentru tine și pentru popor. Apoi adu jertfa poporului și fă ispășire pentru ei, așa cum a poruncit DOMNUL.”", "Aaron s-a apropiat de altar și a junghiat vițelul jertfei pentru păcat care era pentru sine.", "Fiii lui Aaron i-au adus sângele, iar el și-a muiat degetul în sânge, a pus pe coarnele altarului și a turnat celălalt sânge la baza altarului.", "Grăsimea, rinichii și rețeaua ficatului din jertfa pentru păcat le-a ars pe altar, așa cum îi poruncise DOMNUL lui Moise.", "Iar carnea și pielea le-a ars în foc afară din tabără.", "A junghiat apoi arderea-de-tot, fiii lui Aaron i-au dat sângele, iar el l-a stropit pe altar de jur împrejur.", "I-au dat arderea-de-tot bucată cu bucată, împreună cu capul, iar el le-a ars pe altar.", "A spălat măruntaiele și picioarele și le-a ars peste arderea-de-tot pe altar.", "Aaron a adus jertfa poporului. A luat țapul jertfei pentru păcat a poporului, l-a înjunghiat și l-a adus ca jertfă pentru păcat, asemenea celei dintâi.", "A adus arderea-de-tot și a pregătit-o după rânduială.", "A adus darul de cereale, a luat un pumn plin din ea și a ars-o pe altar, pe lângă arderea-de-tot de dimineață.", "A junghiat taurul și berbecul ca jertfă de pace pentru popor. Fiii lui Aaron i-au predat sângele, iar el l-a stropit pe altar de jur împrejur.", "Grăsimile din taur și din berbec, coada întreagă, grăsimea care acoperă măruntaiele, rinichii și rețeaua ficatului,", "le-au pus pe piepturi, iar el a ars grăsimile pe altar.", "Piepturile și pulpa dreaptă Aaron le-a legănat ca dar legănat înaintea DOMNULUI, așa cum poruncise Moise.", "Aaron și-a ridicat mâinile spre popor și l-a binecuvântat. Apoi a coborât după ce adusese jertfa pentru păcat, arderea-de-tot și jertfele de pace.", "Moise și Aaron au intrat în Cortul Întâlnirii, iar când au ieșit, au binecuvântat poporul. Slava DOMNULUI s-a arătat întregului popor.", "Un foc a ieșit dinaintea DOMNULUI și a mistuit arderea-de-tot și grăsimea de pe altar. Când tot poporul a văzut, a strigat de bucurie și a căzut cu fața la pământ."],
    10: ["Nadab și Abihu, fiii lui Aaron, și-au luat fiecare fărașul pentru cărbuni, au pus foc în el, au așezat tămâie deasupra și au adus înaintea DOMNULUI un foc neautorizat, pe care El nu li-l poruncise.", "Atunci un foc a ieșit dinaintea DOMNULUI și i-a mistuit. Ei au murit înaintea DOMNULUI.", "Moise i-a spus lui Aaron: „Acesta este lucrul despre care a vorbit DOMNUL: «Îmi voi arăta sfințenia prin cei care se apropie de Mine și voi fi glorificat înaintea întregului popor.»” Aaron a tăcut.", "Moise i-a chemat pe Mișael și pe Elțafan, fiii lui Uziel, unchiul lui Aaron, și le-a zis: „Apropiați-vă și duceți pe frații voștri din fața Sfântului Lăcaș afară din tabără.”", "Ei s-au apropiat și i-au dus îmbrăcați în tunicile lor afară din tabără, așa cum spusese Moise.", "Moise le-a spus lui Aaron și fiilor săi Eleazar și Itamar: „Să nu vă lăsați părul neîngrijit și să nu vă sfâșiați hainele, ca să nu muriți și ca mânia să nu vină peste întreaga comunitate. Frații voștri, întreaga casă a lui Israel, să jelească arderea pe care a aprins-o DOMNUL.", "Să nu ieșiți de la intrarea Cortului Întâlnirii, ca să nu muriți, căci uleiul ungerii DOMNULUI este peste voi.” Ei au făcut după cuvântul lui Moise.", "DOMNUL i-a vorbit lui Aaron, spunând:", "„Tu și fiii tăi să nu beți vin sau băutură tare când intrați în Cortul Întâlnirii, ca să nu muriți. Aceasta să fie o rânduială veșnică pentru generațiile voastre,", "ca să puteți face deosebire între ce este sfânt și ce este obișnuit, între ce este necurat și ce este curat,", "și să-i învățați pe fiii lui Israel toate rânduielile pe care le-a rostit DOMNUL prin Moise.”", "Moise le-a zis lui Aaron, lui Eleazar și lui Itamar, fiii lui rămași: „Luați darul de cereale ce a rămas din jertfele mistuite de foc ale DOMNULUI și mâncați-o fără aluat lângă altar, căci este un lucru preasfânt.", "Să o mâncați într-un loc sfânt, pentru că este partea ta și partea fiilor tăi din jertfele mistuite de foc ale DOMNULUI; căci așa mi s-a poruncit.", "Pieptul darului legănat și pulpa contribuției să le mâncați într-un loc curat, tu, fiii și fiicele tale împreună cu tine, căci v-au fost date ca parte din jertfele de pace ale fiilor lui Israel.", "Vor aduce pulpa ridicată și pieptul legănat împreună cu jertfele mistuite de foc ale grăsimilor, pentru a le legăna ca dar legănat înaintea DOMNULUI; ele vor fi ale tale și ale fiilor tăi împreună cu tine prin rânduială veșnică, așa cum a poruncit DOMNUL.”", "Moise a căutat cu grijă țapul jertfei pentru păcat și iată că fusese ars. S-a mâniat pe Eleazar și pe Itamar, fiii lui Aaron care rămăseseră, și a spus:", "„De ce nu ați mâncat jertfa pentru păcat în locul sfânt? Ea este preasfântă și v-a fost dată ca să purtați nelegiuirea comunității și să faceți ispășire pentru ea înaintea DOMNULUI.", "Iată că sângele ei nu a fost dus în interiorul Sfântului Lăcaș; trebuia neapărat să o mâncați în Sfântul Lăcaș, așa cum am poruncit!”", "Aaron i-a spus lui Moise: „Iată, astăzi și-au adus jertfa pentru păcat și arderea-de-tot înaintea DOMNULUI, iar mie mi s-au întâmplat asemenea lucruri. Dacă aș fi mâncat astăzi jertfa pentru păcat, ar fi fost oare plăcut în ochii DOMNULUI?”", "Când Moise a auzit, lucrul acesta a fost plăcut în ochii lui."],
    11: ["DOMNUL le-a vorbit lui Moise și lui Aaron, spunându-le:", "„Vorbiți fiilor lui Israel și spune-le: Iată viețuitoarele pe care le veți putea mânca dintre toate animalele de pe pământ:", "Orice animal care are copita despicată, adică despărțită în două, și care rumegă printre animale, pe acela îl veți mânca.", "Dar din cele ce numai rumegă sau numai au copita despicată să nu mâncați: cămila, pentru că rumegă, dar nu are copita despicată; ea este necurată pentru voi;", "iepurele de stâncă, pentru că rumegă, dar nu are copita despicată; este necurat pentru voi;", "iepurele de câmp, pentru că rumegă, dar nu are copita despicată; este necurat pentru voi;", "și porcul, pentru că are copita despicată și despicată în două, dar nu rumegă; este necurat pentru voi.", "Din carnea lor să nu mâncați și de stârvurile lor să nu vă atingeți; sunt necurate pentru voi.", "Iată ce veți mânca din tot ce este în ape: tot ce are înotătoare și solzi în ape, în mări și în râuri, pe acelea le veți mânca.", "Dar tot ce nu are înotătoare și solzi în mări și în râuri, dintre toate vietățile care mișună în ape și dintre toate ființele vii din ape, să fie o urâciune pentru voi.", "Ele vor fi o urâciune pentru voi; din carnea lor să nu mâncați și stârvurile lor să le priviți ca pe o urâciune.", "Tot ce nu are înotătoare și solzi în ape va fi o urâciune pentru voi.", "Dintre păsări, iată pe cele pe care le veți privi ca pe o urâciune și care nu se vor mânca, fiind o urâciune: vulturul, zăganul și vulturul de mare,", "gaia, șoimul după soiurile lui,", "toate soiurile de corbi,", "struțul, cucuveaua, pescărușul și uliul după soiurile lui,", "cucuveaua de stâncă, corbul de apă și bufnița,", "lebăda, pelicanul și vulturul pleșuv,", "barza, stârcul după soiurile lui, pupăza și liliacul.", "Orice insectă înaripată care umblă pe patru picioare să fie o urâciune pentru voi.", "Dar din toate insectele înaripate care umblă pe patru picioare le veți putea mânca pe cele care au picioare lungi deasupra labelor, cu care să sară pe pământ.", "Iată pe care le veți mânca dintre ele: lăcusta după soiurile ei, lăcusta solam după soiurile ei, lăcusta hargol după soiurile ei și lăcusta hagav după soiurile ei.", "Dar orice altă insectă înaripată care are patru picioare să fie o urâciune pentru voi.", "Prin acestea vă veți întina; oricine se va atinge de stârvurile lor va fi necurat până seara,", "iar oricine va purta ceva din stârvul lor să-și spele hainele și va fi necurat până seara.", "Orice animal care are copita despicată, dar nu copita despărțită în două și care nu rumegă, este necurat pentru voi; oricine se va atinge de ele va fi necurat.", "Toate animalele care umblă pe labe dintre toate cele pe patru picioare sunt necurate pentru voi; oricine se va atinge de stârvul lor va fi necurat până seara.", "Iar cine va purta stârvul lor să-și spele hainele și va fi necurat până seara; ele sunt necurate pentru voi.", "Iată ce va fi necurat pentru voi dintre vietățile care mișună pe pământ: nevăstuica, șoarecele și șopârla mare, după soiurile lor,", "gecko, șopârla de zid, șopârla de nisip, șopârla și cameleonul.", "Acestea sunt necurate pentru voi dintre toate vietățile care mișună; oricine se va atinge de ele când sunt moarte va fi necurat până seara.", "Orice lucru peste care va cădea vreuna din ele când este moartă va fi necurat, fie vas de lemn, fie haină, fie piele, fie sac, orice vas folosit la vreo muncă; să fie pus în apă și va fi necurat până seara, apoi va fi curat.", "Dacă va cădea într-un vas de lut, tot ce este în el va fi necurat și vasul îl veți sparge.", "Orice hrană care se mănâncă, peste care va cădea apă dintr-un astfel de vas, va fi necurată; și orice băutură care se bea dintr-un astfel de vas va fi necurată.", "Orice lucru peste care va cădea vreo parte din stârvul lor va fi necurat; cuptorul sau plita să fie dărâmate, căci sunt necurate și vor fi necurate pentru voi.", "Numai un izvor sau o fântână în care se adună apă vor rămâne curate, dar cine se va atinge de stârvul lor va fi necurat.", "Dacă va cădea o parte din stârvul lor pe vreo sămânță de semănat, ea va rămâne curată;", "dar dacă s-a pus apă pe sămânță și va cădea pe ea o parte din stârvul lor, ea va fi necurată pentru voi.", "Dacă moare un animal din cele pe care le puteți mânca, cine se va atinge de stârvul lui va fi necurat până seara.", "Cine va mânca din stârvul lui să-și spele hainele și va fi necurat până seara; și cine va purta stârvul lui să-și spele hainele și va fi necurat până seara.", "Orice vietate care se târăște pe pământ este o urâciune; să nu se mănânce.", "Tot ce se târăște pe pântece, tot ce umblă pe patru picioare sau are multe picioare, dintre toate vietățile care mișună pe pământ, să nu le mâncați, căci sunt o urâciune.", "Să nu vă faceți urâcioși prin nicio vietate care se târăște și să nu vă întinați prin ele, ca să nu deveniți necurați prin ele.", "Căci Eu sunt DOMNUL Dumnezeul vostru. Sfințiți-vă și fiți sfinți, căci Eu sunt sfânt! Să nu vă întinați sufletele prin nicio vietate care se târăște pe pământ.", "Căci Eu sunt DOMNUL, Care v-am scos din țara Egiptului ca să vă fiu Dumnezeu. Fiți dar sfinți, căci Eu sunt sfânt!", "Aceasta este legea privitoare la animale, la păsări, la toate ființele vii care se mișcă în ape și la toate vietățile care mișună pe pământ,", "ca să deosebiți între ce este necurat și ce este curat, între vietățile care se pot mânca și vietățile care nu se pot mânca.”"],
    12: ["DOMNUL i-a vorbit lui Moise, spunând:", "„Vorbește fiilor lui Israel și spune-le: Dacă o femeie va zămisli și va naște un băiat, va fi necurată șapte zile; va fi necurată ca în zilele necurăției menstruației ei.", "În ziua a opta, copilul să fie tăiat împrejur în carnea prepuțului său.", "Ea va mai rămâne treizeci și trei de zile în sângele curățirii ei; să nu se atingă de niciun lucru sfânt și să nu intre în Sfântul Lăcaș până când nu se vor împlini zilele curățirii ei.", "Dar dacă va naște o fată, va fi necurată două săptămâni, ca la menstruația ei, și va rămâne șaizeci și șase de zile pentru curățirea sângelui ei.", "Când se vor împlini zilele curățirii ei pentru un fiu sau pentru o fiică, să aducă preotului la intrarea Cortului Întâlnirii un miel de un an ca ardere-de-tot și un pui de porumbel sau o turturea ca jertfă pentru păcat.", "Preotul le va aduce înaintea DOMNULUI și va face ispășire pentru ea, și va fi curățită de scurgerea sângelui ei. Aceasta este legea pentru cea care naște un băiat sau o fată.", "Iar dacă mijloacele ei nu-i îngăduie să aducă un miel, să ia două turturele sau doi pui de porumbel, unul ca ardere-de-tot și celălalt ca jertfă pentru păcat. Preotul va face ispășire pentru ea și va fi curată.”"],
    13: ["DOMNUL le-a vorbit lui Moise și lui Aaron, spunând:", "Când un om va avea pe pielea trupului său o umflătură, o erupție sau o pată albă, iar aceasta va deveni pe pielea trupului său o plagă de lepră, să fie adus la preotul Aaron sau la unul dintre fiii lui, preoții.", "Preotul să examineze rana de pe pielea trupului; dacă părul de pe rană s-a făcut alb și rana pare mai adâncă decât pielea trupului, este o rană de lepră. Preotul să îl examineze și să îl declare necurat.", "Dar dacă pata de pe pielea trupului său este albă și nu pare mai adâncă decât pielea, iar părul ei nu s-a făcut alb, preotul să îl izoleze pe cel cu rana timp de șapte zile.", "Preotul să îl examineze în ziua a șaptea; dacă rana a rămas palidă și nu s-a întins pe piele, preotul să îl mai izoleze șapte zile.", "Preotul să-l examineze din nou în ziua a șaptea; dacă plaga a pălit și nu s-a întins pe piele, preotul să-l declare curat: este o erupție. El să-și spele hainele și va fi curat.", "Dar dacă erupția se va întinde pe piele după ce s-a arătat preotului pentru curățirea sa, să se arate din nou preotului.", "Preotul îl va examina; dacă erupția s-a întins pe piele, preotul îl va declara necurat: este lepră.", "Când va fi pe un om o rană de lepră, să fie adus la preot.", "Preotul îl va examina; dacă este o umflătură albă pe piele, care a făcut părul alb și dacă este carne vie în umflătură,", "este o lepră veche pe pielea trupului său. Preotul îl va declara necurat; nu îl va izola, căci este necurat.", "Dar dacă lepra va izbucni pe piele și va acoperi toată pielea celui cu rana, de la cap până la picioare, pretutindeni unde privesc ochii preotului,", "preotul îl va examina; dacă lepra a acoperit tot trupul lui, îl va declara curat pe cel cu rana: s-a făcut alb peste tot, este curat.", "Dar în ziua când se va vedea în el carne vie, va fi necurat.", "Preotul va vedea carnea vie și îl va declara necurat; carnea vie este necurată, este lepră.", "Dacă însă carnea vie se va schimba și se va face iarăși albă, să vină la preot.", "Preotul îl va examina; dacă rana s-a făcut albă, preotul îl va declara curat pe cel cu rana: este curat.", "Când trupul va avea pe piele o bubă și ea s-a vindecat,", "iar în locul bubei va fi o umflătură albă sau o pată alb-roșiatică, să se arate preotului.", "Preotul o va examina; dacă pare mai lăsată decât pielea și părul ei s-a făcut alb, preotul îl va declara necurat: este o rană de lepră care a izbucnit în bubă.", "Dar dacă preotul o examinează și iată că nu este păr alb pe ea, nu este mai lăsată decât pielea și este palidă, preotul să îl izoleze șapte zile.", "Dacă s-a întins pe piele, preotul îl va declara necurat: este o rană de lepră.", "Dar dacă pata albă a rămas în locul ei și nu s-a întins, este cicatricea bubei; preotul îl va declara curat.", "Sau când trupul va avea pe piele o arsură de foc, iar locul viu al arsurii devine o pată alb-roșiatică sau albă,", "preotul o va examina; dacă părul de pe pată s-a făcut alb și ea pare mai adâncă decât pielea, este lepră izbucnită în arsură. Preotul îl va declara necurat: este o rană de lepră.", "Dar dacă preotul o examinează și iată că nu este păr alb pe pată, ea nu este mai adâncă decât pielea și este palidă, preotul să îl izoleze șapte zile.", "Preotul îl va examina în ziua a șaptea; dacă s-a întins pe piele, preotul îl va declara necurat: este o rană de lepră.", "Dar dacă pata a rămas la locul ei, nu s-a întins pe piele și este palidă, este umflătura arsurii. Preotul îl va declara curat, căci este cicatricea arsurii.", "Când un bărbat sau o femeie va avea o rană pe cap sau pe barbă,", "preotul va examina rana; dacă ea pare mai adâncă decât pielea și este pe ea păr galben și subțire, preotul îl va declara necurat: este râie, adică lepra capului sau a bărbii.", "Dar dacă preotul examinează rana de râie și iată că ea nu pare mai adâncă decât pielea și nu este păr negru pe ea, preotul să îl izoleze pe cel cu rana de râie șapte zile.", "Preotul va examina rana în ziua a șaptea; dacă râia nu s-a întins, nu este păr galben pe ea și râia nu pare mai adâncă decât pielea,", "omul se va rade, dar râia nu o va rade; iar preotul îl va izola pe cel cu râia încă șapte zile.", "Preotul va examina râia în ziua a șaptea; dacă râia nu s-a întins pe piele și nu pare mai adâncă decât pielea, preotul îl va declara curat. El își va spăla hainele și va fi curat.", "Dar dacă râia se va întinde pe piele după curățirea lui,", "preotul îl va examina; dacă râia s-a întins pe piele, preotul nu va mai căuta părul galben: este necurat.", "Dar dacă în ochii lui râia a rămas neschimbată și a crescut păr negru pe ea, râia s-a vindecat: este curat și preotul îl va declara curat.", "Când un bărbat sau o femeie va avea pe pielea trupului pete, adică pete albe,", "preotul le va examina; dacă petele de pe pielea trupului lor sunt alb-palide, este o pată albă izbucnită pe piele: el este curat.", "Dacă unui bărbat îi cade părul de pe cap, el este chel, dar este curat.", "Dacă îi cade părul din fața capului, este chel în frunte, dar este curat.", "Dar dacă pe chelie sau pe chelia din frunte va fi o rană alb-roșiatică, este lepră izbucnită pe chelia lui sau pe chelia din fruntea lui.", "Preotul îl va examina; dacă umflătura ranei este alb-roșiatică pe chelia lui sau pe chelia din frunte, arătând ca lepra de pe pielea trupului,", "omul acela este lepros, este necurat. Preotul îl va declara necurat; rana lui este pe cap.", "Leprosul care are această rană să aibă hainele sfâșiate, capul descoperit, să-și acopere barba și să strige: „Necurat! Necurat!”", "Toate zilele cât va fi rana pe el va fi necurat. Este necurat; va locui singur, locuința lui va fi afară din tabără.", "Dacă într-o haină va apărea o plagă de lepră, fie într-o haină de lână, fie într-una de in,", "fie pe urzeală, fie pe bătătură, de in sau de lână, fie pe o piele sau pe orice lucru de piele,", "dacă rana este verzuie sau roșiatică pe haină sau pe piele, pe urzeală sau pe bătătură, sau pe orice lucru de piele, este o rană de lepră și se va arăta preotului.", "Preotul va examina rana și va izola lucrul cu rana șapte zile.", "Va examina rana în ziua a șaptea; dacă rana s-a întins pe haină, pe urzeală sau pe bătătură, sau pe piele, pentru orice lucrare la care se folosește pielea, rana este o lepră distrugătoare: lucrul este necurat.", "Va arde haina sau urzeala, ori bătătura de lână sau de in, ori orice lucru de piele pe care se află rana, căci este o lepră distrugătoare; să fie ars în foc.", "Dar dacă preotul examina și iată că rana nu s-a întins pe haină, pe urzeală sau pe bătătură, ori pe orice lucru de piele,", "preotul va porunci să se spele lucrul pe care este rana și îl va mai izola șapte zile.", "Preotul va examina rana după ce a fost spălată; dacă rana nu și-a schimbat înfățișarea, deși nu s-a întins, lucrul este necurat: să îl arzi în foc, este o rosură pe fața sau pe spatele lui.", "Dar dacă preotul examinează și iată că rana a devenit palidă după ce a fost spălată, o va rupe din haină sau din piele, ori din urzeală sau din bătătură.", "Dacă va mai apărea pe haină, pe urzeală sau pe bătătură, ori pe orice lucru de piele, este o lepră izbucnită; să arzi în foc lucrul pe care este rana.", "Dar haina, urzeala sau bătătura, ori orice lucru de piele pe care îl vei spăla și de pe care va dispărea rana, să fie spălat a doua oară și va fi curat.", "Aceasta este legea ranei de lepră de pe o haină de lână sau de in, de pe urzeală sau de pe bătătură, ori de pe orice lucru de piele, pentru a o declara curată sau necurată."],
    14: ["DOMNUL i-a vorbit lui Moise, spunând:", "Aceasta este legea pentru cel bolnav de lepră, în ziua curățirii lui: să fie adus la preot.", "Preotul va ieși afară din tabără și îl va examina; dacă rana de lepră s-a vindecat pe lepros,", "preotul va porunci să se ia pentru cel ce trebuie curățit două păsări vii și curate, lemn de cedru, fir de cârmâz și isop.", "Preotul va porunci să se junghie una din păsări într-un vas de lut, deasupra unei ape curgătoare.", "Va lua pasărea vie, lemnul de cedru, firul de cârmâz și isopul și le va muia, împreună cu pasărea vie, în sângele păsării junghiate deasupra apei curgătoare.", "Va stropi de șapte ori pe cel ce trebuie curățit de lepră și îl va declara curat; apoi va lăsa pasărea vie să zboare pe câmp.", "Cel ce se curățește își va spăla hainele, își va rade tot părul și se va scălda în apă, și va fi curat. După aceea va intra în tabără, dar va rămâne afară din cortul său șapte zile.", "În ziua a șaptea își va rade tot părul, capul, barba și sprâncenele; își va rade tot părul, își va spăla hainele, își va scălda trupul în apă și va fi curat.", "În ziua a opta va lua doi miei fără cusur și o oaie de un an fără cusur, trei zecimi de efă de făină fină frământată cu ulei ca dar de mâncare și un log de ulei.", "Preotul care face curățirea îl va înfățișa pe omul ce se curățește, împreună cu aceste lucruri, înaintea DOMNULUI, la intrarea Cortului Întâlnirii.", "Preotul va lua un miel și îl va aduce ca jertfă pentru vină, împreună cu logul de ulei, și le va legăna ca dar legănat înaintea DOMNULUI.", "Va junghia mielul în locul unde se junghie jertfa pentru păcat și arderea-de-tot, într-un loc sfânt; căci cum este jertfa pentru păcat, așa este și jertfa pentru vină: este a preotului, este un lucru preasfânt.", "Preotul va lua din sângele jertfei pentru vină și va pune pe lobul urechii drepte a celui ce se curățește, pe degetul mare al mâinii lui drepte și pe degetul mare al piciorului lui drept.", "Preotul va lua din logul de ulei și va turna în palma mâinii sale stângi.", "Preotul își va muia degetul drept în uleiul din palma stângă și va stropi cu degetul din ulei de șapte ori înaintea DOMNULUI.", "Din restul uleiului care este în palma sa, preotul va pune pe lobul urechii drepte a celui ce se curățește, pe degetul mare al mâinii lui drepte și pe degetul mare al piciorului lui drept, peste sângele jertfei pentru vină.", "Iar ce va mai rămâne din uleiul din palma sa, preotul va pune pe capul celui ce se curățește; astfel preotul va face ispășire pentru el înaintea DOMNULUI.", "Preotul va aduce jertfa pentru păcat și va face ispășire pentru cel ce se curățește de necurăția lui; după aceea va junghia arderea-de-tot.", "Preotul va aduce pe altar arderea-de-tot și darul de cereale; astfel preotul va face ispășire pentru el și va fi curat.", "Dar dacă este sărac și mijloacele nu-i îngăduie atât, va lua un singur miel ca jertfă pentru vină, ca dar legănat pentru a face ispășire pentru el, o zecime de efă de făină fină frământată cu ulei ca dar de mâncare, un log de ulei,", "și două turturele sau doi pui de porumbel, după mijloacele lui, unul ca jertfă pentru păcat și celălalt ca ardere-de-tot.", "Le va aduce în ziua a opta pentru curățirea sa preotului, la intrarea Cortului Întâlnirii, înaintea DOMNULUI.", "Preotul va lua mielul jertfei pentru vină și logul de ulei și preotul le va legăna ca dar legănat înaintea DOMNULUI.", "Va junghia mielul jertfei pentru vină, preotul va lua din sângele jertfei pentru vină și va pune pe lobul urechii drepte a celui ce se curățește, pe degetul mare al mâinii lui drepte și pe degetul mare al piciorului lui drept.", "Preotul va turna din ulei în palma mâinii sale stângi.", "Preotul va stropi cu degetul său drept din uleiul din palma stângă de șapte ori înaintea DOMNULUI.", "Preotul va pune din uleiul din palma sa pe lobul urechii drepte a celui ce se curățește, pe degetul mare al mâinii lui drepte și pe degetul mare al piciorului lui drept, în locul unde a pus sângele jertfei pentru vină.", "Iar ce va mai rămâne din uleiul din palma sa, preotul va pune pe capul celui ce se curățește, ca să facă ispășire pentru el înaintea DOMNULUI.", "Va pregăti una din turturele sau unul din puii de porumbel, după ce-i îngăduie mijloacele,", "din ce-i îngăduie mijloacele: una ca jertfă pentru păcat și cealaltă ca ardere-de-tot, împreună cu darul de cereale. Astfel preotul va face ispășire înaintea DOMNULUI pentru cel ce se curățește.", "Aceasta este legea pentru cel ce are o rană de lepră și ale cărui mijloace nu-i îngăduie mai mult pentru curățirea sa.", "DOMNUL le-a vorbit lui Moise și lui Aaron, spunând:", "Când veți intra în țara Canaanului, pe care v-o dau în stăpânire, și voi pune o plagă de lepră într-o casă din țara stăpânirii voastre,", "proprietarul casei să vină și să-i spună preotului: „Mi se pare că este o rană pe casă.”", "Preotul va porunci să se golească casa înainte ca preotul să intre să examineze rana, ca să nu devină necurat tot ce este în casă; după aceea preotul va intra să examineze casa.", "Va examina rana; dacă rana de pe zidurile casei este formată din adâncituri verzui sau roșiatice, care apar mai adâncite decât zidul,", "preotul va ieși din casă, la ușa casei, și va închide casa timp de șapte zile.", "Preotul se va întoarce în ziua a șaptea și o va examina; dacă rana s-a întins pe zidurile casei,", "preotul va porunci să se scoată pietrele pe care este rana și să se arunce afară din cetate, într-un loc necurat.", "Va răzui casa în interior de jur împrejur, iar tencuiala pe care au răzuit-o o vor arunca într-un loc necurat din afara cetății.", "Vor lua alte pietre și le vor pune în locul acelor pietre; vor lua altă tencuială și vor tencui casa.", "Dar dacă rana va izbucni din nou pe casă, după ce au scos pietrele și după ce casa a fost rasă și tencuită,", "preotul va intra și o va examina; dacă rana s-a întins pe casă, este o lepră distrugătoare pe casă: ea este necurată.", "Va dărâma casa, pietrele ei, lemnul ei și toată tencuiala casei, și le va scoate afară din cetate, într-un loc necurat.", "Cine va intra în casă în tot timpul cât a fost închisă va fi necurat până seara.", "Cine va dormi în casă își va spăla hainele, și cine va mânca în casă își va spăla hainele.", "Dar dacă preotul va intra și va examina și iată că rana nu s-a întins pe casă după ce a fost tencuită, preotul va declara casa curată, căci rana s-a vindecat.", "Pentru curățirea casei va lua două păsări, lemn de cedru, fir de cârmâz și isop.", "Va junghia una din păsări într-un vas de lut, deasupra unei ape curgătoare.", "Va lua lemnul de cedru, isopul, firul de cârmâz și pasărea vie și le va muia în sângele păsării junghiate și în apa curgătoare, și va stropi casa de șapte ori.", "Va curăți casa cu sângele păsării, cu apa curgătoare, cu pasărea vie, cu lemnul de cedru, cu isopul și cu firul de cârmâz.", "Apoi va lăsa pasărea vie să zboare afară din cetate, pe câmp; astfel va face ispășire pentru casă și ea va fi curată.", "Aceasta este legea pentru orice rană de lepră și pentru râie,", "pentru lepra de pe o haină și de pe o casă,", "pentru umflătură, pentru erupție și pentru pată,", "ca să se învețe când ceva este necurat și când este curat. Aceasta este legea leprei."],
    15: ["DOMNUL le-a vorbit lui Moise și lui Aaron, spunând:", "„Vorbiți fiilor lui Israel și spune-le: Când un bărbat va avea o scurgere din trupul său, scurgerea lui este necurată.", "Iată în ce constă necurăția scurgerii lui: fie că trupul său lasă să curgă scurgerea, fie că trupul său este oprit de la scurgerea sa, este necurăția lui.", "Orice pat pe care se va culca cel ce are scurgerea va fi necurat, și orice lucru pe care se va așeza va fi necurat.", "Cine se va atinge de patul lui să-și spele hainele, să se scalde în apă și va fi necurat până seara.", "Cine se va așeza pe lucrul pe care a șezut cel ce are scurgerea să-și spele hainele, să se scalde în apă și va fi necurat până seara.", "Cine se va atinge de trupul celui ce are scurgerea să-și spele hainele, să se scalde în apă și va fi necurat până seara.", "Dacă cel ce are scurgerea va scuipa pe cineva curat, acela să-și spele hainele, să se scalde în apă și va fi necurat până seara.", "Orice șa pe care va încăleca cel ce are scurgerea va fi necurată.", "Oricine se va atinge de ceva ce a fost sub el va fi necurat până seara; și cine va purta acele lucruri să-și spele hainele, să se scalde în apă și va fi necurat până seara.", "Oricine va fi atins de cel ce are scurgerea, fără ca acesta să-și fi spălat mâinile în apă, să-și spele hainele, să se scalde în apă și va fi necurat până seara.", "Vasul de lut pe care îl va atinge cel ce are scurgerea să fie spart, iar orice vas de lemn să fie spălat cu apă.", "Când cel ce are scurgerea se va curăți de scurgerea lui, să numere șapte zile pentru curățirea sa, să-și spele hainele, să-și scalde trupul în apă curgătoare și va fi curat.", "În ziua a opta să ia două turturele sau doi pui de porumbel, să vină înaintea DOMNULUI, la intrarea Cortului Întâlnirii, și să-i dea preotului.", "Preotul îi va aduce, unul ca jertfă pentru păcat și celălalt ca ardere-de-tot; astfel preotul va face ispășire pentru el înaintea DOMNULUI de scurgerea lui.", "Dacă un bărbat va avea o scurgere seminală, să-și scalde tot trupul în apă și va fi necurat până seara.", "Orice haină și orice piele pe care va fi scurgere seminală să fie spălate cu apă și vor fi necurate până seara.", "Dacă un bărbat se culcă cu o femeie și are o scurgere seminală, amândoi să se scalde în apă și vor fi necurați până seara.", "Când o femeie va avea o scurgere, și scurgerea din trupul ei va fi sânge, va rămâne șapte zile în necurăția menstruației ei; oricine se va atinge de ea va fi necurat până seara.", "Tot ce se va culca ea în timpul necurăției ei va fi necurat, și tot pe ce se va așeza va fi necurat.", "Cine se va atinge de patul ei să-și spele hainele, să se scalde în apă și va fi necurat până seara.", "Cine se va atinge de vreun lucru pe care s-a așezat ea să-și spele hainele, să se scalde în apă și va fi necurat până seara.", "Dacă ceva este pe pat sau pe lucrul pe care s-a așezat ea, când cineva se va atinge de el va fi necurat până seara.", "Dacă un bărbat se culcă cu ea și necurăția ei vine peste el, va fi necurat șapte zile, și orice pat pe care se va culca va fi necurat.", "Dacă o femeie va avea o scurgere de sânge timp de multe zile în afara timpului menstruației ei, sau dacă scurgerea ei durează peste timpul menstruației, în toate zilele scurgerii necurăției ei va fi ca în zilele menstruației ei: este necurată.", "Orice pat pe care se va culca în toate zilele scurgerii ei va fi pentru ea ca patul menstruației ei; și orice lucru pe care se va așeza va fi necurat, ca în necurăția menstruației ei.", "Oricine se va atinge de ele va fi necurat; să-și spele hainele, să se scalde în apă și va fi necurat până seara.", "Dar când se va curăți de scurgerea ei, va număra șapte zile, iar după aceea va fi curată.", "În ziua a opta să ia două turturele sau doi pui de porumbel și să-i aducă preotului, la intrarea Cortului Întâlnirii.", "Preotul va pregăti unul ca jertfă pentru păcat și celălalt ca ardere-de-tot; astfel preotul va face ispășire pentru ea înaintea DOMNULUI de scurgerea necurăției ei.", "Așa să-i feriți pe fiii lui Israel de necurăția lor, ca să nu moară în necurăția lor, întinând lăcașul Meu care este în mijlocul lor.", "Aceasta este legea pentru cel ce are o scurgere, pentru cel ce are o scurgere seminală prin care devine necurat,", "pentru cea aflată în necurăția menstruației, pentru cel ce are o scurgere, fie bărbat, fie femeie, și pentru bărbatul care se culcă cu o femeie necurată.”"],
    16: ["DOMNUL i-a vorbit lui Moise după moartea celor doi fii ai lui Aaron, când s-au apropiat de DOMNUL și au murit.", "DOMNUL i-a zis lui Moise: „Spune-i fratelui tău Aaron să nu intre oricând în Locul Preasfânt, dincolo de perdea, înaintea capacului ispășirii de pe chivot, ca să nu moară, căci Eu Mă voi arăta în nor deasupra capacului ispășirii.", "Iată cum va intra Aaron în Sfântul Lăcaș: cu un taur din cireadă ca jertfă pentru păcat și un berbec ca ardere-de-tot.", "Se va îmbrăca cu tunica sfântă de in, va avea izmenele de in pe trup, se va încinge cu brâul de in și își va pune pe cap mitra de in; acestea sunt veșminte sfinte. Își va scălda trupul în apă și apoi se va îmbrăca cu ele.", "De la adunarea fiilor lui Israel va lua doi țapi ca jertfă pentru păcat și un berbec ca ardere-de-tot.", "Aaron va aduce taurul jertfei pentru păcat care este pentru sine și va face ispășire pentru sine și pentru casa lui.", "Va lua cei doi țapi și îi va înfățișa înaintea DOMNULUI, la intrarea Cortului Întâlnirii.", "Aaron va trage la sorți pentru cei doi țapi: un sorț pentru DOMNUL și un sorț pentru Azazel.", "Aaron va aduce țapul peste care a căzut sorțul pentru DOMNUL și îl va pregăti ca jertfă pentru păcat.", "Iar țapul peste care a căzut sorțul pentru Azazel va fi înfățișat viu înaintea DOMNULUI, pentru a face ispășire peste el și pentru a fi trimis la Azazel, în pustie.", "Aaron va aduce taurul jertfei pentru păcat care este pentru sine și va face ispășire pentru sine și pentru casa lui, și va junghia taurul jertfei pentru păcat care este pentru sine.", "Va lua o cădelniță plină cu cărbuni aprinși de pe altarul dinaintea DOMNULUI și doi pumni plini de tămâie mirositoare pisată mărunt, și le va duce dincoace de perdea.", "Să pună tămâia pe foc înaintea DOMNULUI, pentru ca norul de tămâie să acopere capacul ispășirii care este deasupra Mărturiei, ca să nu moară.", "Să ia din sângele taurului și să stropească cu degetul pe partea dinspre răsărit a capacului ispășirii; iar înaintea capacului ispășirii să stropească din sânge de șapte ori cu degetul.", "Va junghia apoi țapul jertfei pentru păcat care este pentru popor și va duce sângele lui dincoace de perdea. Va face cu sângele lui cum a făcut cu sângele taurului: va stropi cu el pe capacul ispășirii și în fața capacului ispășirii.", "Astfel va face ispășire pentru Sfântul Lăcaș, din cauza necurățiilor fiilor lui Israel și din cauza abaterilor lor, pentru toate păcatele lor. Așa va face și pentru Cortul Întâlnirii, care rămâne cu ei în mijlocul necurățiilor lor.", "Niciun om să nu fie în Cortul Întâlnirii când va intra el să facă ispășire în Sfântul Lăcaș, până când va ieși și va face ispășire pentru sine, pentru casa lui și pentru toată adunarea lui Israel.", "Va ieși la altarul care este înaintea DOMNULUI și va face ispășire pentru el: va lua din sângele taurului și din sângele țapului și va pune pe coarnele altarului de jur împrejur.", "Va stropi pe el din sânge cu degetul de șapte ori, îl va curăți și îl va sfinți de necurățiile fiilor lui Israel.", "Când va termina de făcut ispășire pentru Sfântul Lăcaș, pentru Cortul Întâlnirii și pentru altar, va aduce țapul cel viu.", "Aaron își va pune ambele mâini pe capul țapului viu și va mărturisi peste el toate nelegiuirile fiilor lui Israel, toate abaterile lor și toate păcatele lor; le va pune pe capul țapului și îl va trimite în pustie prin intermediul unui om pregătit.", "Țapul va purta asupra lui toate nelegiuirile lor într-un pământ pustiu, iar omul va lăsa țapul să plece în pustie.", "Aaron va intra în Cortul Întâlnirii, își va dezbrăca veșmintele de in pe care le îmbrăcase când intrase în Sfântul Lăcaș și le va lăsa acolo.", "Să-și scalde trupul în apă într-un loc sfânt, să-și îmbrace veșmintele, apoi să iasă și să aducă arderea-de-tot pentru sine și arderea-de-tot pentru popor, făcând ispășire pentru sine și pentru popor.", "Grăsimea jertfei pentru păcat să o ardă pe altar.", "Cel ce va da drumul țapului pentru Azazel își va spăla hainele, își va scălda trupul în apă și după aceea va putea intra în tabără.", "Taurul jertfei pentru păcat și țapul jertfei pentru păcat, al căror sânge a fost dus în Sfântul Lăcaș pentru a face ispășire, vor fi scoși afară din tabără și le vor arde în foc pieile, carnea și bălegarul.", "Cel ce le va arde își va spăla hainele, își va scălda trupul în apă și după aceea va putea intra în tabără.", "Aceasta va fi pentru voi o rânduială veșnică: în luna a șaptea, în ziua a zecea a lunii, să vă smeriți sufletele și să nu faceți nicio muncă, nici băștinașul, nici străinul care locuiește în mijlocul vostru.", "Căci în această zi se va face ispășire pentru voi, ca să fiți curățiți; veți fi curățiți de toate păcatele voastre înaintea DOMNULUI.", "Va fi pentru voi un Sabat de odihnă deplină și vă veți smeri sufletele; este o rânduială veșnică.", "Preotul care va fi uns și consacrat ca să slujească în locul tatălui său va face ispășirea; se va îmbrăca cu veșmintele de in, veșmintele sfinte.", "Va face ispășire pentru Sfântul Lăcaș, va face ispășire pentru Cortul Întâlnirii și pentru altar, și va face ispășire pentru preoți și pentru tot poporul adunării.", "Aceasta va fi pentru voi o rânduială veșnică: să se facă ispășire pentru fiii lui Israel de toate păcatele lor o dată pe an.” Și s-a făcut așa cum îi poruncise DOMNUL lui Moise."],
    17: ["DOMNUL i-a vorbit lui Moise, spunând:", "„Vorbește lui Aaron, fiilor lui și tuturor fiilor lui Israel și spune-le: Iată ce a poruncit DOMNUL, spunând:", "Orice om din casa lui Israel care va junghia un taur, un miel sau o capră în tabără sau afară din tabără,", "fără să-l aducă la intrarea Cortului Întâlnirii ca să-l aducă drept dar DOMNULUI înaintea lăcașului DOMNULUI, omului aceluia i se va socoti vina sângelui: a vărsat sânge și omul acela va fi nimicit din mijlocul poporului său.", "Aceasta pentru ca fiii lui Israel să-și aducă jertfele pe care le junghie pe câmp liber și să le aducă DOMNULUI la intrarea Cortului Întâlnirii, preotului, și să le aducă ca jertfe de pace DOMNULUI.", "Preotul va stropi sângele pe altarul DOMNULUI, la intrarea Cortului Întâlnirii, și va arde grăsimea ca o mireasmă plăcută DOMNULUI.", "Să nu-și mai aducă jertfele demonilor în chip de țapi, după care se prostituează. Aceasta să fie pentru ei o rânduială veșnică, din generație în generație.", "De aceea spune-le: «Orice om din casa lui Israel sau dintre străinii care locuiesc în mijlocul lor, care va aduce o ardere-de-tot sau o jertfă,", "fără să o aducă la intrarea Cortului Întâlnirii ca să o aducă DOMNULUI, omul acela să fie nimicit din poporul său.", "Dacă vreun om din casa lui Israel sau dintre străinii care locuiesc în mijlocul lor va mânca vreun fel de sânge, Îmi voi întoarce Fața împotriva sufletului care a mâncat sânge și îl voi nimici din mijlocul poporului său.", "Căci viața trupului este în sânge, iar Eu vi l-am dat pe altar ca să facă ispășire pentru sufletele voastre; căci sângele face ispășire prin viața din el.", "De aceea am spus fiilor lui Israel: Niciun suflet dintre voi să nu mănânce sânge, și nici străinul care locuiește în mijlocul vostru să nu mănânce sânge.", "Dacă cineva dintre fiii lui Israel sau dintre străinii care locuiesc în mijlocul lor va prinde la vânătoare un animal sau o pasăre care se mănâncă, să-i scurgă sângele și să-l acopere cu țărână.", "Căci viața oricărui trup este sângele lui; de aceea am spus fiilor lui Israel: Să nu mâncați sângele niciunui trup, căci viața oricărui trup este sângele lui; oricine îl va mânca va fi nimicit.", "Orice suflet, fie băștinaș, fie străin, care va mânca dintr-un animal mort de la sine sau sfâșiat, să-și spele hainele, să se scalde în apă și va fi necurat până seara; apoi va fi curat.", "Dar dacă nu-și va spăla hainele și nu-și va scălda trupul, își va purta vina.»”"],
    18: ["DOMNUL i-a vorbit lui Moise, spunând:", "„Vorbește fiilor lui Israel și spune-le: Eu sunt DOMNUL Dumnezeul vostru!", "Să nu faceți după faptele țării Egiptului, în care ați locuit, și să nu faceți după faptele țării Canaanului, în care vă duc; să nu umblați după rânduielile lor.", "Să împliniți judecățile Mele și să păziți rânduielile Mele, ca să umblați în ele. Eu sunt DOMNUL Dumnezeul vostru!", "Păziți rânduielile Mele și judecățile Mele: omul care le va împlini va trăi prin ele. Eu sunt DOMNUL!", "Niciunul dintre voi să nu se apropie de vreo rudă de sânge a sa ca să-i descopere goliciunea. Eu sunt DOMNUL!", "Să nu descoperi goliciunea tatălui tău, adică goliciunea mamei tale: ea este mama ta, să nu-i descoperi goliciunea.", "Să nu descoperi goliciunea nevestei tatălui tău; este goliciunea tatălui tău.", "Să nu descoperi goliciunea surorii tale, fiica tatălui tău sau fiica mamei tale, fie că s-a născut în casă, fie afară.", "Să nu descoperi goliciunea fiicei fiului tău sau a fiicei fiicei tale, căci este însăși goliciunea ta.", "Să nu descoperi goliciunea fiicei nevestei tatălui tău, născută din tatăl tău: ea este sora ta.", "Să nu descoperi goliciunea surorii tatălui tău: ea este ruda de sânge a tatălui tău.", "Să nu descoperi goliciunea surorii mamei tale, căci ea este ruda de sânge a mamei tale.", "Să nu descoperi goliciunea fratelui tatălui tău: să nu te apropii de nevasta lui, căci este mătușa ta.", "Să nu descoperi goliciunea norei tale: ea este nevasta fiului tău, să nu-i descoperi goliciunea.", "Să nu descoperi goliciunea nevestei fratelui tău; este goliciunea fratelui tău.", "Să nu descoperi goliciunea unei femei și a fiicei ei; să nu iei pe fiica fiului ei sau pe fiica fiicei ei ca să le descoperi goliciunea: sunt rude de sânge, este o ticăloșie.", "Să nu iei pe sora nevestei tale ca rivală, descoperindu-i goliciunea alături de ea în timpul vieții ei.", "Să nu te apropii de o femeie în timpul necurăției menstruației ei, ca să-i descoperi goliciunea.", "Să nu te culci cu nevasta aproapelui tău, ca să te întinezi cu ea.", "Să nu dai pe niciunul din copiii tăi ca să fie trecut prin foc lui Molekh și să nu pângărești Numele Dumnezeului tău. Eu sunt DOMNUL!", "Să nu te culci cu un bărbat așa cum se culcă cineva cu o femeie: este o urâciune.", "Să nu te împreunezi cu niciun animal, ca să te întinezi cu el; și nicio femeie să nu se înfățișeze înaintea unui animal ca să se împreuneze cu el: este o perversiune.", "Să nu vă întinați prin niciunul din aceste lucruri; căci prin toate acestea s-au întinat neamurile pe care le izgonesc dinaintea voastră.", "Țara a fost întinată, de aceea am pedepsit-o pentru nelegiuirea ei, iar țara își varsă locuitorii.", "Voi însă păziți rânduielile Mele și judecățile Mele și să nu faceți niciuna din aceste urâciuni, nici băștinașul, nici străinul care locuiește în mijlocul vostru;", "căci toate aceste urâciuni le-au făcut oamenii țării care au fost înaintea voastră și țara a fost întinată.", "Astfel țara nu vă va vărsa din cauza întinării voastre, așa cum a vărsat neamurile care au fost înaintea voastră.", "Căci toți cei ce vor face vreuna din aceste urâciuni, sufletele care le vor face vor fi nimicit din mijlocul poporului lor.", "Păziți dar rânduiala Mea și să nu urmați din obiceiurile urâcioase care s-au practicat înaintea voastră, ca să nu vă întinați prin ele. Eu sunt DOMNUL Dumnezeul vostru!”"],
    19: ["DOMNUL i-a vorbit lui Moise, spunând:", "„Vorbește întregii adunări a fiilor lui Israel și spune-le: Fiți sfinți, căci Eu sunt sfânt, DOMNUL Dumnezeul vostru!", "Fiecare dintre voi să se teamă de mama sa și de tatăl său și să păziți Sabatele Mele. Eu sunt DOMNUL Dumnezeul vostru!", "Să nu vă întoarceți spre idoli și să nu vă faceți dumnezei turnați. Eu sunt DOMNUL Dumnezeul vostru!", "Când veți aduce o jertfă de pace DOMNULUI, să o aduceți în așa fel încât să fiți primiți.", "Să fie mâncată în ziua aducerii ei și a doua zi; iar ce va rămâne până a treia zi să fie ars în foc.", "Dacă se va mânca a treia zi, este un lucru urâcios; nu va fi primită.", "Cine va mânca din ea își va purta vina, pentru că a pângărit ce este sfânt al DOMNULUI; sufletul acela va fi nimicit din poporul său.", "Când veți secera secerișul țării voastre, să nu seceri câmpul până la margini și să nu aduni spicele căzute la seceriș.", "Nici via ta să nu o culegi a doua oară și strugurii căzuți în via ta să nu-i aduni; să le lași pentru cel sărac și pentru străin. Eu sunt DOMNUL Dumnezeul vostru!", "Să nu furați, să nu mințiți și să nu vă înșelați unii pe alții.", "Să nu jurați strâmb pe Numele Meu, pângărind astfel Numele Dumnezeului tău. Eu sunt DOMNUL!", "Să nu asuprești pe aproapele tău și să nu-l jefuiești. Plata argatului să nu rămână la tine până dimineața.", "Să nu blestemi pe cel surd și să nu pui piatră de poticnire înaintea orbului, ci să te temi de Dumnezeul tău. Eu sunt DOMNUL!", "Să nu faceți nedreptate la judecată; să nu cauți la fața celui sărac și să nu părtinești pe cel mare, ci să judeci pe aproapele tău cu dreptate.", "Să nu umbli cu clevetiri în poporul tău și să nu te ridici împotriva sângelui aproapelui tău. Eu sunt DOMNUL!", "Să nu urăști pe fratele tău în inima ta; să dojenești pe aproapele tău, ca să nu te încarci cu păcat din cauza lui.", "Să nu te răzbuni și să nu ții pizmă pe fiii poporului tău, ci să iubești pe aproapele tău ca pe tine însuți. Eu sunt DOMNUL!", "Păziți rânduielile Mele. Să nu împerechezi vitele tale cu vite din altă specie; să nu semeni ogorul tău cu două feluri de semințe și să nu porți o haină țesută din două feluri de fir.", "Dacă un bărbat se culcă cu o femeie și are relații sexuale cu ea, iar ea este sclavă logodită unui alt bărbat, dar nu a fost răscumpărată și nici eliberată, să aibă loc o cercetare; ei să nu fie omorâți, pentru că ea nu fusese eliberată.", "Bărbatul să aducă DOMNULUI ca jertfă pentru vină, la intrarea Cortului Întâlnirii, un berbec ca jertfă pentru vină.", "Preotul va face ispășire pentru el cu berbecul jertfei pentru vină înaintea DOMNULUI, pentru păcatul pe care l-a săvârșit, și păcatul săvârșit îi va fi iertat.", "Când veți intra în țară și veți sădi tot felul de pomi roditori, să le socotiți rodul ca netăiat împrejur; timp de trei ani va fi pentru voi netăiat împrejur; să nu se mănânce.", "În anul al patrulea, tot rodul lor va fi sfânt, un prinos de laudă pentru DOMNUL.", "Iar în anul al cincilea veți putea mânca din rodul lor, ca să vă sporească venitul. Eu sunt DOMNUL Dumnezeul vostru!", "Să nu mâncați nimic cu sânge. Să nu ghiciți și să nu vrăjiți.", "Să nu vă tăiați rotund colțurile părului de pe cap și să nu-ți strici colțurile bărbii.", "Să nu vă faceți crestături pe trup pentru un mort și să nu vă faceți tatuaje pe voi. Eu sunt DOMNUL!", "Să nu-ți pângărești fiica făcând-o să se desfrâneze, ca să nu se desfrâneze țara și să nu se umple țara de ticăloșie.", "Păziți Sabatele Mele și cinstiți Sfântul Meu Lăcaș. Eu sunt DOMNUL!", "Să nu vă întoarceți spre cei ce cheamă duhurile, nici spre vrăjitori; să nu-i căutați ca să vă întinați prin ei. Eu sunt DOMNUL Dumnezeul vostru!", "Să te ridici în fața perilor cărunți, să cinstești fața bătrânului și să te temi de Dumnezeul tău. Eu sunt DOMNUL!", "Dacă un străin va locui cu voi în țara voastră, să nu-l asupriți.", "Străinul care locuiește cu voi să fie pentru voi ca un băștinaș din mijlocul vostru; să-l iubești ca pe tine însuți, căci și voi ați fost străini în țara Egiptului. Eu sunt DOMNUL Dumnezeul vostru!", "Să nu faceți nedreptate la judecată, nici la măsura de lungime, nici la greutate, nici la măsura de capacitate.", "Să aveți balanțe drepte, greutăți drepte, o efă dreaptă și un hin drept. Eu sunt DOMNUL Dumnezeul vostru, Care v-am scos din țara Egiptului!", "Păziți toate rânduielile Mele și toate judecățile Mele și împliniți-le. Eu sunt DOMNUL!”"],
    20: ["DOMNUL i-a vorbit lui Moise, spunând:", "„Spune fiilor lui Israel: Orice om dintre fiii lui Israel sau dintre străinii care locuiesc în Israel, care își va da vreunul din copiii lui lui Molekh, să fie pus la moarte; poporul țării să-l ucidă cu pietre.", "Eu Îmi voi întoarce Fața împotriva omului aceluia și îl voi nimici din mijlocul poporului său, pentru că și-a dat copilul lui Molekh, pângărindu-Mi Sfântul Lăcaș și profanând Numele Meu cel sfânt.", "Dacă poporul țării își va închide ochii față de omul acela când își va da copilul lui Molekh și nu-l va pune la moarte,", "Eu Îmi voi întoarce Fața împotriva omului aceluia și împotriva familiei lui și-l voi nimici din mijlocul poporului lor, pe el și pe toți cei ce se desfrânează ca el, desfrânându-se după Molekh.", "Dacă un suflet se va întoarce spre cei ce cheamă duhurile și spre vrăjitori, ca să se desfrâneze după ei, Îmi voi întoarce Fața împotriva sufletului aceluia și îl voi nimici din mijlocul poporului său.", "Sfințiți-vă dar și fiți sfinți, căci Eu sunt DOMNUL Dumnezeul vostru!", "Păziți rânduielile Mele și împliniți-le. Eu sunt DOMNUL, Care vă sfințesc!", "Căci orice om care își va blestema tatăl sau mama să fie pus la moarte; și-a blestemat tatăl sau mama, sângele lui este asupra lui.", "Dacă un bărbat comite adulter cu nevasta altui bărbat, cu nevasta aproapelui său, adulterul și adultera să fie puși la moarte.", "Bărbatul care se culcă cu nevasta tatălui său a descoperit goliciunea tatălui său; amândoi să fie puși la moarte, sângele lor este asupra lor.", "Dacă un bărbat se culcă cu nora sa, amândoi să fie puși la moarte; au săvârșit o ticăloșie, sângele lor este asupra lor.", "Dacă un bărbat se culcă cu un alt bărbat cum se culcă cineva cu o femeie, amândoi au săvârșit o urâciune; să fie puși la moarte, sângele lor este asupra lor.", "Dacă un bărbat își ia de neveste pe o femeie și pe mama ei, este o nelegiuire; să fie arși în foc, el și ele, ca să nu fie nelegiuire în mijlocul vostru.", "Bărbatul care se împreunează cu un animal să fie pus la moarte, iar voi să ucideți animalul.", "Dacă o femeie se apropie de vreun animal ca să se împreuneze cu el, să ucizi femeia și animalul; să fie puși la moarte, sângele lor este asupra lor.", "Dacă un bărbat își ia pe sora sa, fiica tatălui său sau fiica mamei sale, și îi vede goliciunea, iar ea vede goliciunea lui, este o rușine; să fie nimiciți sub ochii fiilor poporului lor. A descoperit goliciunea surorii sale, își va purta vina.", "Dacă un bărbat se culcă cu o femeie în timpul necurăției ei și îi descoperă goliciunea, i-a descoperit scurgerea și ea și-a descoperit scurgerea sângelui ei; amândoi să fie nimiciți din mijlocul poporului lor.", "Să nu descoperi goliciunea surorii mamei tale sau a surorii tatălui tău, căci s-a descoperit ruda de sânge; își vor purta vina.", "Dacă un bărbat se culcă cu mătușa sa, a descoperit goliciunea unchiului său; își vor purta păcatul, vor muri fără copii.", "Dacă un bărbat își ia pe nevasta fratelui său, este o necurăție; a descoperit goliciunea fratelui său, vor fi fără copii.", "Păziți toate rânduielile Mele și toate judecățile Mele și împliniți-le, ca să nu vă verse țara în care vă duc să locuiți.", "Să nu umblați după obiceiurile neamurilor pe care le izgonesc dinaintea voastră; căci ele au făcut toate aceste lucruri și Mi s-a scârbit de ele.", "Dar vouă v-am spus: Voi veți moșteni pământul lor și Eu vi-l voi da în stăpânire, o țară în care curge lapte și miere. Eu sunt DOMNUL Dumnezeul vostru, Care v-a separat de alte popoare!", "De aceea să faceți deosebire între animalele curate și cele necurate, între păsările necurate și cele curate, ca să nu vă faceți urâcioși sufletele prin animale, prin păsări sau prin tot ce mișună pe pământ, pe care vi le-am separat ca necurate.", "Fiți sfinți pentru Mine, căci Eu, DOMNUL, sunt sfânt și v-am separat de alte popoare ca să fiți ai Mei!", "Un bărbat sau o femeie care va avea un duh de chemare a morților sau un duh de ghicit să fie pus la moarte; să-i ucidă cu pietre, sângele lor este asupra lor.”"],
    21: ["DOMNUL i-a zis lui Moise: „Vorbește preoților, fiilor lui Aaron, și spune-le: Un preot să nu se întineze prin atingerea unui mort din poporul său,", "afară de rudele sale cele mai apropiate: mama sa, tatăl său, fiul său, fiica sa, fratele său,", "și sora sa fecioară, care este aproape de el și care nu a fost măritată; pentru ea se va putea întina.", "Fiind căpetenie în poporul său, să nu se întineze, pângărindu-se.", "Preoții să nu-și facă pleșuvie pe cap, să nu-și radă colțurile bărbii și să nu-și facă crestături pe trup.", "Să fie sfinți pentru Dumnezeul lor și să nu pângărească Numele Dumnezeului lor; căci ei aduc jertfele mistuite de foc ale DOMNULUI, pâinea Dumnezeului lor; de aceea să fie sfinți.", "Să nu-și ia de nevastă o femeie desfrânată sau pângărită și să nu-și ia o femeie alungată de bărbatul ei, căci preotul este sfânt pentru Dumnezeul său.", "Să-l socotești sfânt, căci el aduce pâinea Dumnezeului tău; el va fi sfânt pentru tine, căci Eu, DOMNUL, Care vă sfințesc, sunt sfânt.", "Dacă fiica unui preot se pângărește desfrânându-se, îl pângărește pe tatăl ei; să fie arsă în foc.", "Preotul cel mai mare dintre frații săi, pe capul căruia a fost turnat uleiul ungerii și care a fost consacrat ca să îmbrace veșmintele sfinte, să nu-și despletească părul de pe cap și să nu-și sfâșie hainele.", "Să nu se apropie de niciun mort; să nu se întineze nici chiar pentru tatăl său sau pentru mama sa.", "Să nu iasă din Sfântul Lăcaș și să nu pângărească Sfântul Lăcaș al Dumnezeului său, căci cununa uleiului ungerii Dumnezeului său este peste el. Eu sunt DOMNUL!", "El să-și ia de nevastă o femeie fecioară.", "Să nu ia o văduvă, nici o femeie alungată, nici o femeie pângărită sau desfrânată, ci să-și ia de nevastă o fecioară din poporul său,", "ca să nu-și pângărească urmașii în poporul său; căci Eu sunt DOMNUL, Care îl sfințesc.”", "DOMNUL i-a vorbit lui Moise, spunând:", "„Vorbește-i lui Aaron și spune-i: Niciunul dintre urmașii tăi, din generație în generație, care are un defect trupesc să nu se apropie ca să aducă hrana Dumnezeului său.", "Căci niciun om care are vreun cusur trupesc să nu se apropie: niciun orb, niciun șchiop, niciunul cu nasul ciuntit sau cu un mădular prea lung,", "niciunul care are un picior frânt sau o mână frântă,", "niciun cocoșat, niciun pitic, niciunul care are o pată albă în ochi, niciunul care are râie sau pecingine, sau care are testiculele vătămate.", "Niciun om dintre urmașii preotului Aaron care are vreun cusur trupesc să nu se apropie ca să aducă jertfele mistuite de foc ale DOMNULUI; are un cusur, să nu se apropie ca să aducă pâinea Dumnezeului său.", "El va putea să mănânce din pâinea Dumnezeului său, din lucrurile preasfânte și din lucrurile sfinte;", "dar să nu intre la perdea și să nu se apropie de altar, pentru că are un cusur, ca să nu pângărească Lăcașurile Mele sfinte; căci Eu sunt DOMNUL, Care le sfințesc.”", "Moise a spus aceste lucruri lui Aaron, fiilor lui și tuturor fiilor lui Israel."],
    22: ["DOMNUL i-a vorbit lui Moise, spunând:", "„Spune lui Aaron și fiilor lui să se poarte cu evlavie față de lucrurile sfinte ale fiilor lui Israel, pe care Mi le consacră ei, ca să nu pângărească Numele Meu cel sfânt. Eu sunt DOMNUL!", "Spune-le: Orice om dintre toți urmașii voștri, din neam în neam, care se va apropia de lucrurile sfinte pe care fiii lui Israel le consacră DOMNULUI, având pe el necurăția sa, omul acela va fi nimicit dinaintea Mea. Eu sunt DOMNUL!", "Orice om din urmașii lui Aaron care va avea lepră sau o scurgere să nu mănânce din lucrurile sfinte până nu va fi curat. Cine se va atinge de cineva întinat de un mort, sau cel ce va avea o scurgere seminală,", "sau cel ce se va atinge de vreo vietate prin care se va întina, sau de un om prin care se va întina, indiferent de necurăția lui,", "omul care se va atinge de acestea va fi necurat până seara și să nu mănânce din lucrurile sfinte până nu-și va scălda trupul în apă.", "După ce va apune soarele, va fi curat, iar după aceea va putea mânca din lucrurile sfinte, căci ele sunt hrana lui.", "Să nu mănânce dintr-un animal mort de la sine sau sfâșiat, ca să nu se întineze prin el. Eu sunt DOMNUL!", "Să păzească porunca Mea, ca să nu se încarce cu păcat din cauza ei și să nu moară în ea pentru că au pângărit-o. Eu sunt DOMNUL, Care îi sfințesc!", "Niciun străin să nu mănânce din lucrurile sfinte; nici oaspetele preotului, nici argatul lui să nu mănânce din lucrurile sfinte.", "Dar dacă preotul cumpără un rob cu banii lui, acela va putea mânca din ele; și cel născut în casa lui va putea mânca din hrana lui.", "Dacă fiica unui preot se mărită cu un străin, ea să nu mănânce din prinosul lucrurilor sfinte.", "Dar dacă fiica preotului rămâne văduvă sau alungată, fără să aibă copii, și se întoarce în casa tatălui ei ca în tinerețea ei, va putea mânca din hrana tatălui ei; dar niciun străin să nu mănânce din ea.", "Dacă cineva mănâncă din greșeală dintr-un lucru sfânt, să adauge o cincime peste valoarea lui și să-i dea preotului lucrul sfânt.", "Preoții să nu pângărească lucrurile sfinte ale fiilor lui Israel, pe care le aduc DOMNULUI,", "încărcându-i cu vina abaterii când mănâncă lucrurile lor sfinte; căci Eu sunt DOMNUL, Care îi sfințesc!”", "DOMNUL i-a vorbit lui Moise, spunând:", "„Vorbește lui Aaron, fiilor lui și tuturor fiilor lui Israel și spune-le: Orice om din casa lui Israel sau dintre străinii din Israel, care își va aduce prinosul, fie pentru vreo juruință, fie ca dar de bunăvoie pe care îl aduc DOMNULUI ca ardere-de-tot,", "ca să fiți primiți, să aduceți un mascul fără cusur din cireadă, din miei sau din capre.", "Să nu aduceți niciun animal care are vreun cusur, căci nu va fi primit pentru voi.", "Dacă cineva aduce DOMNULUI o jertfă de pace din cireadă sau din turmă, fie pentru împlinirea unei juruințe, fie ca dar de bunăvoie, animalul să fie fără cusur ca să fie primit; să nu aibă niciun cusur pe el.", "Animal orb, cu mădular frânt, ciuntit, cu negi, cu râie sau cu pecingine să nu aduceți DOMNULUI și să nu puneți din ele ca jertfă mistuită de foc pe altar pentru DOMNUL.", "Un taur sau un miel care are un mădular prea lung sau prea scurt îl vei putea aduce ca dar de bunăvoie, dar pentru o juruință nu va fi primit.", "Animal cu boașele strivite, zdrobite, rupte sau tăiate să nu aduceți DOMNULUI și în țara voastră să nu faceți așa ceva.", "Nici din mâna unui străin să nu aduceți hrana Dumnezeului vostru din toate acestea; căci stricăciunea lor este în ele, au cusur pe ele, nu vor fi primite pentru voi.”", "DOMNUL i-a vorbit lui Moise, spunând:", "„Când se va naște un taur, un miel sau o capră, să rămână șapte zile cu mama lui; iar din ziua a opta și după aceea va fi primit ca prinos de jertfă mistuită de foc pentru DOMNUL.", "Vacă sau oaie, să nu o junghiați în aceeași zi împreună cu puiul ei.", "Când veți aduce DOMNULUI o jertfă de mulțumire, să o aduceți în așa fel încât să fiți primiți.", "Să fie mâncată în aceeași zi; să nu lăsați nimic din ea până dimineața. Eu sunt DOMNUL!", "Păziți poruncile Mele și împliniți-le. Eu sunt DOMNUL!", "Să nu pângăriți Numele Meu cel sfânt, ci Eu voi fi sfințit în mijlocul fiilor lui Israel. Eu sunt DOMNUL, Care vă sfințesc,", "Care v-am scos din țara Egiptului ca să vă fiu Dumnezeu. Eu sunt DOMNUL!”"],
    23: ["DOMNUL i-a vorbit lui Moise, spunând:", "„Vorbește fiilor lui Israel și spune-le: Sărbătorile DOMNULUI, pe care le veți vesti ca adunări sfinte, iată sărbătorile Mele:", "Șase zile să se lucreze, dar ziua a șaptea este Sabatul de odihnă deplină, o adunare sfântă; să nu faceți nicio muncă în ea: este Sabatul DOMNULUI în toate locuințele voastre.", "Iată sărbătorile DOMNULUI, adunările sfinte pe care le veți vesti la vremurile lor rânduite:", "În luna întâi, în ziua a paisprezecea a lunii, între cele două seri, sunt Paștele DOMNULUI.", "Iar în ziua a cincisprezecea a aceleiași luni este Sărbătoarea Azimilor pentru DOMNUL: șapte zile veți mânca azime.", "În ziua întâi veți avea o adunare sfântă; să nu faceți nicio muncă de slugă în ea.", "Timp de șapte zile veți aduce DOMNULUI jertfe mistuite de foc. În ziua a șaptea va fi o adunare sfântă; să nu faceți nicio muncă de slugă în ea.”", "DOMNUL i-a vorbit lui Moise, spunând:", "„Vorbește fiilor lui Israel și spune-le: Când veți intra în țara pe care v-o dau și veți secera secerișul ei, să aduceți preotului primul snop din secerișul vostru.", "Preotul va legăna snopul înaintea DOMNULUI ca să fiți primiți; a doua zi după Sabat îl va legăna preotul.", "În ziua când veți legăna snopul, veți aduce un miel de un an fără cusur ca ardere-de-tot DOMNULUI,", "împreună cu jertfa lui de mâncare: două zecimi de efă de făină fină frământată cu ulei, ca jertfă mistuită de foc de o mireasmă plăcută DOMNULUI, și jertfa lui de turnare: un sfert de hin de vin.", "Să nu mâncați nici pâine, nici spice prăjite, nici spice noi până în ziua aceasta, până când nu veți fi adus prinosul Dumnezeului vostru. Aceasta este o rânduială veșnică pentru generațiile voastre în toate locuințele voastre.", "Din a doua zi după Sabat, din ziua în care veți fi adus snopul legănat, veți număra șapte săptămâni întregi.", "Până în a doua zi după a șaptea săptămână veți număra cincizeci de zile, iar atunci veți aduce DOMNULUI un nou prinos de mâncare.", "Din locuințele voastre veți aduce două pâini legănate, făcute din două zecimi de efă de făină fină, coapte cu aluat: sunt primele roade pentru DOMNUL.", "Pe lângă pâine veți aduce șapte miei de un an fără cusur, un taur din cireadă și doi berbeci; ei vor fi o ardere-de-tot DOMNULUI, împreună cu jertfa lor de mâncare și jertfele lor de turnare, o jertfă mistuită de foc de o mireasmă plăcută DOMNULUI.", "Veți pregăti un țap ca jertfă pentru păcat și doi miei de un an ca jertfă de pace.", "Preotul le va legăna împreună cu pâinea primelor roade ca dar legănat înaintea DOMNULUI, împreună cu cei doi miei; ele vor fi sfinte pentru DOMNUL și vor fi ale preotului.", "În aceeași zi veți vesti o adunare sfântă; să nu faceți nicio muncă de slugă în ea: este o rânduială veșnică în toate locuințele voastre pentru generațiile voastre.", "Când veți secera secerișul țării voastre, să nu seceri câmpul până la margini și să nu aduni spicele căzute la seceriș; să le lași pentru cel sărac și pentru străin. Eu sunt DOMNUL Dumnezeul vostru!”", "DOMNUL i-a vorbit lui Moise, spunând:", "„Vorbește-le fiilor lui Israel și spune-le: În luna a șaptea, în prima zi a lunii, să aveți o odihnă solemnă, o aducere-aminte prin sunet de trâmbiță, o adunare sfântă.", "Să nu faceți nicio muncă de slugă în ea și să aduceți DOMNULUI jertfe mistuite de foc.”", "DOMNUL i-a vorbit lui Moise, spunând:", "„În ziua a zecea a acestei luni a șaptea va fi Ziua Ispășirii: veți avea o adunare sfântă, vă veți smeri sufletele și veți aduce DOMNULUI jertfe mistuite de foc.", "Să nu faceți nicio muncă în această zi, căci este Ziua Ispășirii, când se face ispășire pentru voi înaintea DOMNULUI Dumnezeului vostru.", "Orice suflet care nu se va smeri în această zi va fi nimicit din poporul său.", "Și pe orice suflet care va face vreo muncă în această zi îl voi nimici din mijlocul poporului său.", "Să nu faceți nicio muncă: este o rânduială veșnică pentru generațiile voastre în toate locuințele voastre.", "Va fi pentru voi un Sabat de odihnă deplină și vă veți smeri sufletele. În ziua a noua a lunii, seara, de la apus până la apusul următor, veți prăznui Sabatul vostru.”", "DOMNUL i-a vorbit lui Moise, spunând:", "„Vorbește fiilor lui Israel și spune-le: În ziua a cincisprezecea a acestei luni a șaptea este Sărbătoarea Corturilor, timp de șapte zile pentru DOMNUL.", "În ziua întâi va fi o adunare sfântă; să nu faceți nicio muncă de slugă în ea.", "Timp de șapte zile veți aduce DOMNULUI jertfe mistuite de foc. În ziua a opta veți avea o adunare sfântă și veți aduce DOMNULUI jertfe mistuite de foc; este o adunare de sărbătoare, să nu faceți nicio muncă de slugă în ea.", "Acestea sunt sărbătorile DOMNULUI pe care le veți vesti ca adunări sfinte, ca să aduceți DOMNULUI jertfe mistuite de foc: arderi de tot, daruri de cereale, jertfe și jertfe de turnare, fiecare lucru la ziua lui rânduită,", "pe lângă Sabatele DOMNULUI, pe lângă darurile voastre, pe lângă toate juruințele voastre și pe lângă toate darurile de bunăvoie pe care le veți da DOMNULUI.", "În ziua a cincisprezecea a lunii a șaptea, când veți strânge roadele țării, veți prăznui sărbătoarea DOMNULUI timp de șapte zile: prima zi va fi o zi de odihnă și ziua a opta va fi o zi de odihnă.", "În ziua întâi veți lua roade din copacii frumoși, ramuri de curmal, ramuri de copaci stufoși și salcii de râu, și vă veți bucura înaintea DOMNULUI Dumnezeului vostru timp de șapte zile.", "Să praznuiți această sărbătoare pentru DOMNUL timp de șapte zile pe an: este o rânduială veșnică pentru generațiile voastre; în luna a șaptea să o praznuiți.", "Veți locui în colibe timp de șapte zile; toți băștinașii din Israel să locuiască în colibe,", "pentru ca generațiile voastre să știe că am făcut pe fiii lui Israel să locuiască în colibe când i-am scos din țara Egiptului. Eu sunt DOMNUL Dumnezeul vostru!”", "Așa a vestit Moise fiilor lui Israel sărbătorile DOMNULUI."],
    24: ["DOMNUL i-a vorbit lui Moise, spunând:", "„Poruncește fiilor lui Israel să-ți aducă ulei curat de măsline stors pentru sfeșnic, ca să ardă candelele necontenit.", "În Cortul Întâlnirii, dincoace de perdea Mărturiei, Aaron îl va rândui să ardă de seara până dimineața înaintea DOMNULUI necontenit: este o rânduială veșnică pentru generațiile voastre.", "Va așeza candelele pe sfeșnicul de aur curat înaintea DOMNULUI necontenit.", "Vei lua făină fină și vei coace din ea douăsprezece turte; fiecare turtă va fi făcută din două zecimi de efă.", "Le vei așeza în două șiruri, câte șase în șir, pe masa de aur curat înaintea DOMNULUI.", "Vei pune tămâie curată pe fiecare șir, ca ea să fie pentru pâine o aducere aminte, o jertfă mistuită de foc pentru DOMNUL.", "În fiecare zi de Sabat le va așeza înaintea DOMNULUI necontenit; este un legământ veșnic din partea fiilor lui Israel.", "Ele vor fi ale lui Aaron și ale fiilor lui, și le vor mânca într-un loc sfânt; căci este un lucru preasfânt pentru el din jertfele mistuite de foc ale DOMNULUI, prin rânduială veșnică.”", "Fiul unei femei israelite și al unui bărbat egiptean a ieșit în mijlocul fiilor lui Israel; și fiul femeii israelite s-a certat în tabără cu un bărbat israelit.", "Fiul femeii israelite a hulit Numele și L-a blestemat. Atunci l-au adus la Moise. Mama lui se numea Șelomit, fiica lui Dibri, din seminția lui Dan.", "L-au pus sub pază până când li se va lămuri ce să facă după porunca DOMNULUI.", "DOMNUL i-a vorbit lui Moise, spunând:", "„Scoate-l pe cel ce a blestemat afară din tabără; toți cei ce l-au auzit să-și pună mâinile pe capul lui și toată adunarea să-l ucidă cu pietre.", "Iar fiilor lui Israel spune-le astfel: Orice om care își va blestema Dumnezeul își va purta vina.", "Cine va huli Numele DOMNULUI să fie pedepsit cu moartea: toată adunarea să-l ucidă cu pietre. Fie străin, fie băștinaș, când va huli Numele, să fie omorât.", "Cine va ucide un om să fie pedepsit cu moartea.", "Cine va ucide un animal să-l restituie: suflet pentru suflet.", "Dacă cineva va pricinui o vătămare aproapelui său, să i se facă așa cum a făcut el:", "frântură pentru frântură, ochi pentru ochi, dinte pentru dinte; cum a pricinuit el o vătămare unui om, așa să i se facă.", "Cine va ucide un animal să-l restituie, dar cine va ucide un om să fie omorât.", "O singură judecată veți avea, atât pentru străin, cât și pentru băștinaș; căci Eu sunt DOMNUL Dumnezeul vostru!”", "Moise le-a vorbit fiilor lui Israel și l-au scos pe cel ce blestemase afară din tabără și l-au ucis cu pietre. Fiii lui Israel au făcut așa cum îi poruncise DOMNUL lui Moise."],
    25: ["DOMNUL i-a vorbit lui Moise pe Muntele Sinai, spunând:", "„Vorbește fiilor lui Israel și spune-le: Când veți intra în țara pe care v-o dau, pământul să prăznuiască un Sabat pentru DOMNUL.", "Șase ani să-ți semeni ogorul și șase ani să-ți cureți via și să-i strângi roadele;", "dar în anul al șaptelea va fi un Sabat de odihnă deplină pentru pământ, un Sabat pentru DOMNUL: ogorul tău să nu-l semeni și via ta să nu o cureți.", "Ce va crește de la sine din secerișul tău să nu seceri și strugurii din via ta necurățată să nu-i culegi: va fi un an de odihnă pentru pământ.", "Ce va da pământul în timpul Sabatului său vă va sluji de hrană: ție, slujitorului tău, slujitoarei tale, argatului tău și străinului care locuiește cu tine,", "precum și animalelor tale și fiarelor din țara ta; tot venitul lui va fi de hrană.", "Vei număra șapte săptămâni de ani, adică de șapte ori câte șapte ani, astfel că timpul celor șapte săptămâni de ani va fi de patruzeci și nouă de ani.", "În luna a șaptea, în ziua a zecea a lunii, vei face să sune trâmbița răsunătoare; în Ziua Ispășirii veți face să sune trâmbița în toată țara voastră.", "Să sfințiți anul al cincizecilea și să proclamați libertatea în țară pentru toți locuitorii ei. Acesta va fi pentru voi un Jubileu: fiecăruia dintre voi i se va reda moșia și fiecare se va întoarce la familia sa.", "Anul al cincizecilea va fi pentru voi un Jubileu: să nu semănați, să nu secerați ce va crește de la sine și să nu culegeți strugurii din viile necurățate.", "Căci este Jubileul: va fi sfânt pentru voi; veți mânca venitul crescut de pe câmp.", "În acest an de Jubileu vă veți întoarce fiecare la moșia sa.", "Dacă vindeți ceva aproapelui vostru sau cumpărați ceva din mâna aproapelui vostru, să nu vă înșelați unii pe alții.", "Să cumperi de la aproapele tău socotind numărul anilor de după Jubileu, iar el să-ți vândă socotind numărul anilor de rod.", "Cu cât vor fi mai mulți ani, cu atât vei mări prețul, și cu cât vor fi mai puțini ani, cu atât vei micșora prețul; căci el îți vinde numărul secerișurilor.", "Să nu vă înșelați unii pe alții, ci să te temi de Dumnezeul tău; căci Eu sunt DOMNUL Dumnezeul vostru!", "Împliniți rânduielile Mele și păziți judecățile Mele și faceți-le, ca să locuiți în siguranță în țară.", "Pământul își va da rodul, veți mânca pe săturate și veți locui în siguranță în el.", "Iar dacă veți întreba: «Ce vom mânca în anul al șaptelea, dacă nu vom semăna și nu vom strânge roadele noastre?»,", "Eu vă voi trimite binecuvântarea Mea în anul al șaselea și el va da rod pentru trei ani.", "În anul al optulea veți semăna și veți mânca din vechile roade; până în anul al nouălea, până va veni rodul lui, veți mânca din cel vechi.", "Pământul să nu se vândă pentru totdeauna, căci pământul este al Meu; voi sunteți străini și venetici la Mine.", "În toată țara stăpânirii voastre să acordați dreptul de răscumpărare pentru pământ.", "Dacă fratele tău sărăcește și își vinde o parte din moșia lui, ruda lui cea mai apropiată să vină și să răscumpere ce a vândut fratele său.", "Dacă un om nu are pe cineva care să răscumpere, dar își sporește mijloacele și găsește cât trebuie pentru răscumpărarea sa,", "să socotească anii de la vânzare, să restituie restul cumpărătorului și să se întoarcă la moșia sa.", "Dar dacă nu găsește mijloace să-i restituie, ce a vândut va rămâne în mâna cumpărătorului până la anul de Jubileu; iar la Jubileu va fi eliberat și omul se va întoarce la moșia sa.", "Dacă cineva vinde o casă de locuit dintr-o cetate zidită, va avea drept de răscumpărare până la împlinirea unui an de la vânzarea ei; dreptul lui de răscumpărare va dura un an întreg.", "Dar dacă nu este răscumpărată înainte de împlinirea unui an întreg, casa din cetatea zidită va rămâne pentru totdeauna cumpărătorului și urmașilor lui; nu va fi eliberată la Jubileu.", "Casele din satele nezidite de jur împrejur vor fi socotite ca ogoarele țării: vor avea drept de răscumpărare și la Jubileu vor fi eliberate.", "Cât despre cetățile leviților și casele din cetățile stăpânirii lor, leviții vor avea un drept veșnic de răscumpărare.", "Dacă cineva cumpără de la leviți o casă, casa vândută în cetatea stăpânirii lor va fi eliberată la Jubileu; căci casele din cetățile leviților sunt moșia lor în mijlocul fiilor lui Israel.", "Iar ogorul din jurul cetăților lor să nu se vândă, căci este moșia lor veșnică.", "Dacă fratele tău sărăcește și se clatină lângă tine, să-l sprijini; ca străin și venetic să trăiască cu tine.", "Să nu iei de la el dobândă, nici spor, ci să te temi de Dumnezeul tău, ca fratele tău să trăiască cu tine.", "Să nu-i dai banii tăi cu dobândă și să nu-i dai hrana ta pentru câștig.", "Eu sunt DOMNUL Dumnezeul vostru, Care v-am scos din țara Egiptului ca să vă dau țara Canaanului și să vă fiu Dumnezeu!", "Dacă fratele tău sărăcește lângă tine și ți se vinde ție, să nu-l pui la muncă de rob;", "să fie la tine ca un argat, ca un venetic; până la anul de Jubileu va sluji la tine.", "Atunci va pleca de la tine, el și copiii lui împreună cu el, și se va întoarce la familia sa și la moșia părinților săi.", "Căci ei sunt slujitorii Mei, pe care i-am scos din țara Egiptului; să nu fie vânduți cum se vând sclavii.", "Să nu-l stăpânești cu asprime, ci să te temi de Dumnezeul tău.", "Robii și roabele pe care le vei avea să fie din neamurile din jurul vostru; din ele veți cumpăra robi și roabe.", "Veți putea cumpăra și din copiii veneticilor care locuiesc la voi și din familiile lor care sunt la voi, născuți în țara voastră; ei vor fi moșia voastră.", "Îi veți lăsa moștenire fiilor voștri după voi, ca moșie de stăpânit; îi veți avea ca robi pentru totdeauna. Dar peste frații voștri, fiii lui Israel, niciunul să nu stăpânească peste altul cu asprime.", "Dacă un străin sau un venetic de la tine devine bogat, iar fratele tău sărăcește lângă el și se vinde străinului sau veneticului de la tine, ori vreunuia din familia străinului,", "după ce s-a vândut va avea dreptul de răscumpărare; unul din frații lui îl va putea răscumpăra,", "sau unchiul lui, sau fiul unchiului lui îl va putea răscumpăra, sau o rudă de sânge din familia lui îl va putea răscumpăra; sau, dacă își va spori mijloacele, se va răscumpăra singur.", "Va socoti cu cel ce l-a cumpărat de la anul când i s-a vândut până la anul de Jubileu; prețul vânzării lui se va potrivi cu numărul anilor, iar zilele lui vor fi socotite ca zilele unui argat.", "Dacă mai sunt mulți ani, va restitui din prețul cumpărării sale prețul răscumpărării în raport cu ei;", "iar dacă au mai rămas puțini ani până la anul de Jubileu, va socoti cu el și își va restitui prețul răscumpărării în raport cu anii lui.", "Va fi la el ca un argat tocmit de la an la an; el să nu-l stăpânească cu asprime sub ochii tăi.", "Iar dacă nu este răscumpărat prin aceste mijloace, va ieși liber la anul de Jubileu, el și copiii lui împreună cu el.", "Căci fiii lui Israel sunt slujitorii Mei; sunt slujitorii Mei pe care i-am scos din țara Egiptului. Eu sunt DOMNUL Dumnezeul vostru!”"],
    26: ["„Să nu vă faceți idoli, să nu vă ridicați chip cioplit nici stâlp sfânt și să nu puneți în țara voastră nicio piatră cu chipuri ca să vă închinați înaintea ei; căci Eu sunt DOMNUL Dumnezeul vostru!", "Păziți Sabatele Mele și cinstiți Sfântul Meu Lăcaș. Eu sunt DOMNUL!", "Dacă veți umbla după rânduielile Mele și dacă veți păzi poruncile Mele și le veți împlini,", "vă voi da ploi la vremea lor, pământul își va da rodul și pomii de pe câmp își vor da rodul.", "Treieratul vă va ține până la culesul strugurilor, iar culesul strugurilor va ține până la semănat; veți mânca pâinea voastră pe săturate și veți locui în siguranță în țara voastră.", "Voi da pace în țară, vă veți culca și nimeni nu vă va înspăimânta; voi face să piară fiarele rele din țară și sabia nu va trece prin țara voastră.", "Veți urmări pe vrăjmașii voștri și ei vor cădea de sabie înaintea voastră.", "Cinci dintre voi vor urmări o sută, și o sută dintre voi vor urmări zece mii, iar vrăjmașii voștri vor cădea de sabie înaintea voastră.", "Mă voi întoarce spre voi, vă voi face roditori, vă voi înmulți și Îmi voi întări legământul cu voi.", "Veți mânca din roadele vechi, strânse de mult, și le veți scoate afară pe cele vechi ca să faceți loc celor noi.", "Voi așeza Lăcașul Meu în mijlocul vostru și sufletul Meu nu vă va urî.", "Voi umbla în mijlocul vostru, voi fi Dumnezeul vostru și voi veți fi poporul Meu.", "Eu sunt DOMNUL Dumnezeul vostru, Care v-am scos din țara Egiptului, ca să nu mai fiți robii lor; am frânt jugul vostru și v-am făcut să umblați cu capul ridicat!", "Dar dacă nu Mă veți asculta și nu veți împlini toate aceste porunci,", "dacă veți nesocoti rânduielile Mele și dacă sufletul vostru va urî judecățile Mele, neîmplinind toate poruncile Mele și călcând legământul Meu,", "iată ce vă voi face: voi trimite peste voi groaza, boala mistuitoare și febra, care ard ochii și mistuie viața; vă veți semăna în zadar sămânța, căci o vor mânca vrăjmașii voștri.", "Îmi voi întoarce Fața împotriva voastră și veți fi bătuți înaintea vrăjmașilor voștri; cei ce vă urăsc vor stăpâni peste voi și veți fugi fără să vă urmărească nimeni.", "Dacă nici după acestea nu Mă veți asculta, vă voi pedepsi de șapte ori mai mult pentru păcatele voastre.", "Voi frânge mândria puterii voastre, voi face cerul vostru ca fierul și pământul vostru ca arama.", "Puterea voastră se va consuma în zadar: pământul vostru nu-și va da rodul și pomii țării nu-și vor da rodul.", "Dacă veți umbla împotriva Mea și nu veți voi să Mă ascultați, vă voi lovi de șapte ori mai mult, după păcatele voastre.", "Voi trimite împotriva voastră fiarele câmpului, care vă vor lipsi de copii, vă vor nimici vitele și vă vor împuțina, încât drumurile voastre vor rămâne pustii.", "Dacă nici prin aceste pedepse nu vă veți îndrepta spre Mine, ci veți umbla împotriva Mea,", "voi umbla și Eu împotriva voastră și vă voi lovi de șapte ori mai mult pentru păcatele voastre.", "Voi aduce împotriva voastră sabia răzbunătoare a legământului; iar când vă veți strânge în cetățile voastre, voi trimite ciuma în mijlocul vostru și veți fi dați în mâinile vrăjmașului.", "Când vă voi frânge toiagul pâinii, zece femei vor coace pâinea voastră într-un singur cuptor și vă vor da pâinea cu cântarul; veți mânca, dar nu vă veți sătura.", "Dacă nici după aceasta nu Mă veți asculta, ci veți umbla împotriva Mea,", "voi umbla și Eu cu mânie împotriva voastră și vă voi pedepsi de șapte ori mai mult pentru păcatele voastre.", "Veți mânca carnea fiilor voștri și veți mânca carnea fiicelor voastre.", "Voi nimici înălțimile voastre, voi tăia stâlpii voștri ai soarelui și voi arunca stârvurile voastre peste stârvurile idolilor voștri, iar sufletul Meu vă va urî.", "Voi preface cetățile voastre în dărâmături, voi pustii Lăcașurile voastre sfinte și nu voi mai mirosi mirosul plăcut al jertfelor voastre.", "Voi pustii țara, încât vrăjmașii voștri care vor locui în ea vor rămâne încremeniți de ea.", "Iar pe voi vă voi împrăștia printre neamuri și voi scoate sabia după voi; țara voastră va fi pustiită și cetățile voastre vor fi dărâmături.", "Atunci pământul își va bucura Sabatele în toate zilele cât va fi pustiit și cât veți fi în țara vrăjmașilor voștri; atunci pământul se va odihni și își va bucura Sabatele.", "În toate zilele cât va fi pustiit va avea odihna pe care nu a avut-o în Sabatele voastre, când locuiați în el.", "Celor ce vor mai rămâne dintre voi le voi băga frică în inimă în țările vrăjmașilor lor: freamătul unei frunze suflate de vânt îi va pune pe fugă; vor fugi cum se fuge de sabie și vor cădea fără să-i urmărească nimeni.", "Se vor poticni unii de alții ca în fața sabiei, fără să fie vreun urmăritor, și nu veți putea sta în picioare înaintea vrăjmașilor voștri.", "Veți pieri printre neamuri și țara vrăjmașilor voștri vă va mânca.", "Iar cei ce vor mai rămâne dintre voi vor tânji din cauza nelegiuirii lor în țările vrăjmașilor lor, și din cauza nelegiuirilor părinților lor vor tânji împreună cu ei.", "Își vor mărturisi nelegiuirea lor și nelegiuirea părinților lor, abaterile prin care s-au abătut de la Mine și prin care au umblat împotriva Mea,", "din care cauză și Eu am umblat împotriva lor și i-am dus în țara vrăjmașilor lor. Dacă atunci inima lor netăiată împrejur se va smeri și își vor primi pedeapsa nelegiuirii lor,", "Îmi voi aduce aminte de legământul Meu cu Iacov, de legământul Meu cu Isaac și de legământul Meu cu Avraam, și Îmi voi aduce aminte de țară.", "Căci pământul va fi părăsit de ei și își va bucura Sabatele cât va fi pustiit fără ei; iar ei își vor primi pedeapsa nelegiuirii lor, pentru că au nesocotit judecățile Mele și sufletul lor a urât rânduielile Mele.", "Dar chiar și așa, când vor fi în țara vrăjmașilor lor, nu-i voi lepăda și nu-i voi urî până acolo încât să-i nimicesc de tot și să calc legământul Meu cu ei; căci Eu sunt DOMNUL Dumnezeul lor!", "Ci Îmi voi aduce aminte pentru ei de legământul cu strămoșii lor, pe care i-am scos din țara Egiptului sub ochii neamurilor, ca să le fiu Dumnezeu. Eu sunt DOMNUL!”", "Acestea sunt rânduielile, judecățile și legile pe care le-a statornicit DOMNUL între Sine și fiii lui Israel, pe Muntele Sinai, prin Moise."],
    27: ["DOMNUL i-a vorbit lui Moise, spunând:", "„Vorbește fiilor lui Israel și spune-le: Când cineva va face o juruință deosebită DOMNULUI, evaluarea persoanelor va fi a DOMNULUI.", "Evaluarea ta pentru un bărbat de la douăzeci de ani până la șaizeci de ani va fi de cincizeci de șecheli de argint, după șechelul sfântului lăcaș.", "Dacă este femeie, evaluarea ta va fi de treizeci de șecheli.", "Dacă este de la cinci ani până la douăzeci de ani, evaluarea ta pentru un băiat va fi de douăzeci de șecheli, iar pentru o fată de zece șecheli.", "Dacă este de la o lună până la cinci ani, evaluarea ta pentru un băiat va fi de cinci șecheli de argint, iar pentru o fată evaluarea ta va fi de trei șecheli de argint.", "Dacă este de la șaizeci de ani în sus, pentru un bărbat evaluarea ta va fi de cincisprezece șecheli, iar pentru o femeie de zece șecheli.", "Dar dacă este prea sărac pentru evaluarea ta, să fie înfățișat înaintea preotului și preotul îl va evalua; preotul îl va evalua potrivit mijloacelor celui ce a făcut juruința.", "Dacă este vorba de un animal din cele ce se aduc ca prinos DOMNULUI, tot ce se va da DOMNULUI din el va fi sfânt.", "Să nu-l schimbe și să nu-l înlocuiască, nici bun cu rău, nici rău cu bun; iar dacă va înlocui un animal cu altul, atât animalul inițial, cât și cel cu care a fost înlocuit vor fi sfinte.", "Dacă este vorba de un animal necurat din cele ce nu se pot aduce ca prinos DOMNULUI, să înfățișeze animalul înaintea preotului.", "Preotul îl va evalua, fie bun, fie rău; cum îl va evalua preotul, așa va fi.", "Dar dacă va dori să-l răscumpere, să adauge o cincime peste evaluarea ta.", "Când cineva își va consacra casa ca lucru sfânt DOMNULUI, preotul o va evalua, fie bună, fie rea; cum o va evalua preotul, așa va rămâne.", "Dacă cel ce și-a consacrat casa va dori să o răscumpere, să adauge o cincime din banii evaluării tale peste ea și va fi a lui.", "Dacă cineva va consacra DOMNULUI o parte din ogorul moșiei sale, evaluarea ta va fi potrivit semănăturii lui: o semănătură de un homer de orz va fi prețuită la cincizeci de șecheli de argint.", "Dacă își va consacra ogorul din anul de Jubileu, va rămâne potrivit evaluării tale.", "Dar dacă își va consacra ogorul după Jubileu, preotul îi va calcula banii potrivit anilor rămași până la anul de Jubileu și se va scădea din evaluarea ta.", "Dacă cel ce și-a consacrat ogorul va dori să-l răscumpere, să adauge o cincime din banii evaluării tale peste ea și îi va rămâne lui.", "Dar dacă nu va răscumpăra ogorul și dacă ogorul va fi vândut altui om, nu va mai putea fi răscumpărat;", "ci ogorul, când va fi eliberat la Jubileu, va fi sfânt pentru DOMNUL, ca un ogor consacrat prin blestem; moșia lui va fi a preotului.", "Dacă cineva va consacra DOMNULUI un ogor cumpărat de el, care nu este din ogorul moșiei sale,", "preotul îi va calcula suma evaluării tale până la anul de Jubileu și omul va da în ziua aceea suma evaluării ca lucru sfânt DOMNULUI.", "La anul de Jubileu ogorul se va întoarce la cel de la care fusese cumpărat, la cel a cărui moșie era pământul.", "Toate evaluările tale se vor face după șechelul sfântului lăcaș: douăzeci de gere fac un șechel.", "Totuși întâiul născut dintre animale, care aparține DOMNULUI ca întâi născut, nimeni să nu-l consacrice: fie taur, fie miel, este al DOMNULUI.", "Dacă este vorba de un animal necurat, îl va răscumpăra după evaluarea ta, adăugând o cincime peste ea; iar dacă nu este răscumpărat, să fie vândut potrivit evaluării tale.", "Totuși niciun lucru consacrat prin blestem, pe care un om îl va consacra DOMNULUI prin blestem din tot ce are, fie om, fie animal, fie ogorul moșiei sale, nu se va putea vinde și nici răscumpăra: orice lucru consacrat prin blestem este preasfânt pentru DOMNUL.", "Niciun om consacrat prin blestem, care va fi dat nimicii dintre oameni, nu va putea fi răscumpărat; va fi dat la moarte.", "Orice zeciuială din pământ, fie din semințele pământului, fie din rodul pomilor, este a DOMNULUI: este un lucru sfânt pentru DOMNUL.", "Dacă cineva va dori să răscumpere ceva din zeciuiala sa, să adauge o cincime peste ea.", "Orice zeciuială din cireadă și din turmă, din tot ce trece sub toiag, al zecelea va fi sfânt pentru DOMNUL.", "Să nu cerceteze dacă este bun sau rău și să nu-l schimbe; iar dacă îl va schimba, atât el, cât și cel cu care a fost schimbat vor fi sfinte și nu vor putea fi răscumpărate.”", "Acestea sunt poruncile pe care le-a dat DOMNUL lui Moise pentru fiii lui Israel pe Muntele Sinai."],
  },
}
